export const PAGE_HTML = "<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\">\n<title>小市場</title>\n<script src=\"https://cdn.jsdelivr.net/npm/canvas-confetti@1.9.3/dist/confetti.browser.min.js\"></script>\n<style>\n  :root {\n    color-scheme: dark;\n    --bg: #000000;\n    --card: #1c1c1e;\n    --card-hover: #2c2c2e;\n    --panel: #141416;\n    --line: rgba(255, 255, 255, 0.08);\n    --line-light: rgba(255, 255, 255, 0.14);\n    --text: #ffffff;\n    --text-muted: #8e8e93;\n    --text-dim: #636366;\n    --green: #30d158;\n    --green-bg: rgba(48, 209, 88, 0.12);\n    --red: #ff453a;\n    --red-bg: rgba(255, 69, 58, 0.12);\n    --blue: #0a84ff;\n    --blue-bg: rgba(10, 132, 255, 0.14);\n    --gold: #ff9f0a;\n    --gold-bg: rgba(255, 159, 10, 0.14);\n    --radius-sm: 8px;\n    --radius-md: 14px;\n    --radius-lg: 20px;\n    --radius-full: 9999px;\n    --apple-font: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', 'PingFang TC', 'Noto Sans TC', sans-serif;\n    --apple-ease: cubic-bezier(0.25, 1, 0.5, 1);\n    /* Meta Astryx Design Tokens */\n    --astryx-bg-canvas: #090b0e;\n    --astryx-bg-surface: #12161c;\n    --astryx-bg-card: #181e26;\n    --astryx-bg-card-hover: #1f2732;\n    --astryx-border-subtle: rgba(255, 255, 255, 0.08);\n    --astryx-border-focus: #00d674;\n    --astryx-bull-green: #00d674;\n    --astryx-bull-green-bg: rgba(0, 214, 116, 0.12);\n    --astryx-bear-red: #ff3b5c;\n    --astryx-bear-red-bg: rgba(255, 59, 92, 0.12);\n    --astryx-text-primary: #f8fafc;\n    --astryx-text-secondary: #94a3b8;\n    --astryx-text-muted: #64748b;\n\n  }\n\n  *, *::before, *::after {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n  }\n\n  html, body {\n    overflow-x: hidden;\n    width: 100%;\n    max-width: 100vw;\n  }\n\n  body {\n    background: var(--bg);\n    color: var(--text);\n    font-family: var(--apple-font);\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    min-height: 100vh;\n    padding: 0 0 60px;\n    line-height: 1.45;\n    letter-spacing: -0.012em;\n  }\n\n  .wrap {\n    max-width: 1080px;\n    width: 100%;\n    margin: 0 auto;\n    padding: 0 16px;\n    overflow-x: hidden;\n  }\n\n  /* 頂部導航列 - Apple 霧面毛玻璃 */\n  .site-header {\n    position: sticky;\n    top: 0;\n    z-index: 90;\n    backdrop-filter: blur(25px);\n    -webkit-backdrop-filter: blur(25px);\n    background: rgba(0, 0, 0, 0.82);\n    border-bottom: 1px solid var(--line);\n    padding: 12px 16px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 12px;\n    margin: 0 0 16px;\n    width: 100%;\n  }\n\n  .brand-group {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    flex-shrink: 0;\n  }\n\n  .brand-mark {\n    width: 32px;\n    height: 32px;\n    border-radius: 8px;\n    background: linear-gradient(135deg, #2c2c2e, #1c1c1e);\n    border: 1px solid rgba(255, 255, 255, 0.12);\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 16px;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);\n  }\n\n  h1 {\n    font-size: 18px;\n    font-weight: 700;\n    color: #ffffff;\n    letter-spacing: -0.02em;\n    margin: 0;\n    line-height: 1.2;\n  }\n\n  .brand-caption {\n    font-size: 10.5px;\n    font-weight: 500;\n    color: var(--text-muted);\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    margin-top: 1px;\n  }\n\n  .user-badge-bar {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    flex-wrap: wrap;\n    min-width: 0;\n  }\n\n  .whale-chip {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    padding: 4px 10px;\n    background: rgba(255, 255, 255, 0.06);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-full);\n    font-size: 12px;\n    font-weight: 600;\n    color: #ffffff;\n    white-space: nowrap;\n    min-height: 44px;\n  }\n\n  /* Apple HIG 44px 觸控目標標準 */\n  .sound-btn, .recharge-btn, #logout {\n    background: rgba(255, 255, 255, 0.08);\n    border: 1px solid var(--line);\n    color: var(--text);\n    padding: 8px 14px;\n    min-width: 44px;\n    min-height: 44px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    border-radius: var(--radius-full);\n    font-size: 12.5px;\n    font-weight: 500;\n    cursor: pointer;\n    white-space: nowrap;\n    transition: all 0.18s var(--apple-ease);\n  }\n\n  .sound-btn:hover, .recharge-btn:hover, #logout:hover {\n    background: rgba(255, 255, 255, 0.14);\n    transform: translateY(-0.5px);\n  }\n\n  .recharge-btn {\n    color: var(--gold);\n    border-color: rgba(255, 159, 10, 0.25);\n    background: var(--gold-bg);\n  }\n\n  #filter-side, #filter-apply {\n    min-width: 44px;\n    min-height: 44px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  /* 頂部快訊與跑馬燈 - Apple News 典雅風格 */\n  .ticker-marquee {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 8px 12px;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    margin-bottom: 16px;\n    font-size: 12px;\n    overflow: hidden;\n    width: 100%;\n  }\n\n  .ticker-badge {\n    padding: 3px 7px;\n    border-radius: 6px;\n    font-size: 10.5px;\n    font-weight: 700;\n    background: rgba(10, 132, 255, 0.18);\n    color: var(--blue);\n    letter-spacing: 0.04em;\n    flex-shrink: 0;\n  }\n\n  .ticker-text {\n    color: var(--text-muted);\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    min-width: 0;\n    flex: 1;\n    transition: opacity 0.25s var(--apple-ease);\n  }\n\n  /* 總資產看板 - 簡潔精準的 Apple 數字展現 */\n  .portfolio-hero {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-lg);\n    padding: 22px;\n    margin-bottom: 18px;\n    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);\n    overflow: hidden;\n    width: 100%;\n  }\n\n  .portfolio-hero .label {\n    font-size: 12.5px;\n    font-weight: 500;\n    color: var(--text-muted);\n    margin-bottom: 4px;\n    letter-spacing: -0.01em;\n  }\n\n  .portfolio-hero .val-big {\n    display: flex;\n    align-items: baseline;\n    gap: 12px;\n    font-size: 34px;\n    font-weight: 700;\n    color: #ffffff;\n    font-variant-numeric: tabular-nums;\n    letter-spacing: -0.03em;\n    margin-bottom: 16px;\n    flex-wrap: wrap;\n  }\n\n  .pnl-badge {\n    display: inline-flex;\n    align-items: center;\n    padding: 4px 10px;\n    border-radius: 8px;\n    font-size: 12.5px;\n    font-weight: 600;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .pnl-up {\n    background: var(--green-bg);\n    color: var(--green);\n  }\n\n  .pnl-down {\n    background: var(--red-bg);\n    color: var(--red);\n  }\n\n  .cards {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));\n    gap: 10px;\n    padding-top: 14px;\n    border-top: 1px solid var(--line);\n    width: 100%;\n  }\n\n  .card {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 10px 14px;\n    min-width: 0;\n    overflow: hidden;\n    transition: background 0.18s var(--apple-ease);\n  }\n\n  .card:hover {\n    background: rgba(255, 255, 255, 0.05);\n  }\n\n  .card .label {\n    font-size: 11.5px;\n    color: var(--text-muted);\n    margin-bottom: 4px;\n    font-weight: 500;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .card .value {\n    font-size: 15.5px;\n    font-weight: 600;\n    color: #ffffff;\n    font-variant-numeric: tabular-nums;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  /* 頁籤導航 - Apple 分段控制器 (Segmented Control) */\n  .navigation {\n    display: inline-flex;\n    background: #1c1c1e;\n    border: 1px solid var(--line);\n    padding: 3px;\n    border-radius: var(--radius-full);\n    margin-bottom: 18px;\n    gap: 2px;\n    max-width: 100%;\n    overflow-x: auto;\n    scrollbar-width: none;\n    -webkit-overflow-scrolling: touch;\n  }\n\n  .navigation::-webkit-scrollbar {\n    display: none;\n  }\n\n  .navigation button {\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    padding: 6px 16px;\n    min-height: 38px;\n    border-radius: var(--radius-full);\n    font-size: 13px;\n    font-weight: 500;\n    cursor: pointer;\n    flex-shrink: 0;\n    white-space: nowrap;\n    transition: all 0.2s var(--apple-ease);\n  }\n\n  .navigation button:hover {\n    color: #ffffff;\n  }\n\n  .navigation button[aria-current='page'] {\n    background: #2c2c2e;\n    color: #ffffff;\n    font-weight: 600;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);\n  }\n\n  /* 即時黑天鵝／催化劑快訊條 - 雅致 Apple News 卡片 */\n  .market-news-ticker {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 10px 14px;\n    margin-bottom: 16px;\n    cursor: pointer;\n    overflow: hidden;\n    width: 100%;\n    transition: all 0.2s var(--apple-ease);\n  }\n\n  .market-news-ticker:hover {\n    background: var(--card-hover);\n    border-color: rgba(255, 255, 255, 0.16);\n  }\n\n  .ticker-tag {\n    font-size: 11px;\n    font-weight: 700;\n    padding: 3px 7px;\n    border-radius: 6px;\n    background: var(--blue-bg);\n    color: var(--blue);\n    flex-shrink: 0;\n  }\n\n  .market-news-ticker .ticker-text {\n    flex: 1;\n    font-size: 12.5px;\n    font-weight: 500;\n    color: #ffffff;\n    min-width: 0;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  .ticker-impact {\n    font-size: 12px;\n    font-weight: 700;\n    padding: 2px 7px;\n    border-radius: 6px;\n    background: var(--green-bg);\n    color: var(--green);\n    flex-shrink: 0;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .ticker-impact.neg {\n    background: var(--red-bg);\n    color: var(--red);\n  }\n\n  /* 核心股票看板 (Hero Stock Box) - Apple Stocks 旗艦視覺 */\n  .hero-stock-box {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-lg);\n    padding: 20px;\n    margin-bottom: 18px;\n    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.35);\n    overflow: hidden;\n    width: 100%;\n  }\n\n  .hero-stock-head {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 14px;\n    margin-bottom: 16px;\n    flex-wrap: wrap;\n  }\n\n  .hero-stock-title {\n    font-size: 20px;\n    font-weight: 700;\n    color: #ffffff;\n    display: block;\n    line-height: 1.2;\n    letter-spacing: -0.02em;\n  }\n\n  .hero-stock-sym {\n    font-size: 12.5px;\n    color: var(--text-muted);\n    font-weight: 500;\n    margin-top: 2px;\n    display: block;\n  }\n\n  .hero-stock-price {\n    font-size: 32px;\n    font-weight: 700;\n    color: #ffffff;\n    font-variant-numeric: tabular-nums;\n    letter-spacing: -0.03em;\n    margin: 6px 0 4px;\n  }\n\n  .momentum-badge {\n    display: inline-flex;\n    align-items: center;\n    padding: 3px 8px;\n    border-radius: 6px;\n    background: rgba(255, 255, 255, 0.06);\n    color: var(--text-muted);\n    font-size: 11px;\n    font-weight: 600;\n    max-width: 100%;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  /* 多空拔河量表 - 簡約細緻 Apple Health 雙色膠囊 */\n  .tug-of-war-box {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 10px 14px;\n    margin: 14px 0;\n    width: 100%;\n    overflow: hidden;\n  }\n\n  .tug-header {\n    display: flex;\n    justify-content: space-between;\n    font-size: 11.5px;\n    font-weight: 600;\n    color: var(--text-muted);\n    margin-bottom: 6px;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .tug-bull {\n    color: var(--green);\n  }\n\n  .tug-bear {\n    color: var(--red);\n  }\n\n  .tug-title {\n    color: var(--text-dim);\n    font-weight: 500;\n    font-size: 11px;\n  }\n\n  .tug-bar-track {\n    height: 6px;\n    background: #2c2c2e;\n    border-radius: 999px;\n    overflow: hidden;\n    display: flex;\n    width: 100%;\n  }\n\n  .tug-bull-fill {\n    background: var(--green);\n    transition: width 0.3s var(--apple-ease);\n  }\n\n  .tug-bear-fill {\n    background: var(--red);\n    transition: width 0.3s var(--apple-ease);\n  }\n\n  .chart-meta-bar {\n    display: flex;\n    justify-content: space-between;\n    font-size: 11px;\n    color: var(--text-dim);\n    margin-bottom: 8px;\n    font-weight: 500;\n    flex-wrap: wrap;\n    gap: 4px;\n  }\n\n  .hero-chart-container {\n    position: relative;\n    width: 100%;\n    height: 220px;\n    border-radius: var(--radius-md);\n    overflow: hidden;\n    background: rgba(0, 0, 0, 0.2);\n  }\n\n  .hero-chart-container svg {\n    width: 100%;\n    height: 100%;\n    display: block;\n  }\n\n  .chart-scrubber-pill {\n    position: absolute;\n    top: 8px;\n    left: 10px;\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    background: rgba(28, 28, 30, 0.9);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    border: 1px solid rgba(255, 255, 255, 0.12);\n    border-radius: 8px;\n    padding: 5px 10px;\n    font-size: 12px;\n    font-weight: 600;\n    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5);\n    z-index: 5;\n    pointer-events: none;\n    max-width: calc(100% - 20px);\n  }\n\n  /* 股票卡片網格 */\n  .chart-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n    gap: 12px;\n    margin-bottom: 18px;\n    width: 100%;\n  }\n\n  .chart {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 14px;\n    cursor: pointer;\n    overflow: hidden;\n    transition: all 0.2s var(--apple-ease);\n  }\n\n  .chart:hover {\n    background: var(--card-hover);\n    border-color: rgba(255, 255, 255, 0.16);\n  }\n\n  .chart.active-chart {\n    border-color: var(--blue);\n    box-shadow: 0 0 0 1px var(--blue);\n  }\n\n  .chart h3 {\n    font-size: 14.5px;\n    font-weight: 600;\n    color: #ffffff;\n    margin-bottom: 3px;\n  }\n\n  .chart-price {\n    font-size: 18px;\n    font-weight: 700;\n    color: #ffffff;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .chart-note {\n    font-size: 11.5px;\n    color: var(--text-muted);\n    margin-top: 3px;\n  }\n\n  .chart svg {\n    width: 100%;\n    height: 65px;\n    margin: 6px 0;\n    display: block;\n  }\n\n  .chart-action {\n    display: inline-block;\n    padding: 5px 12px;\n    border-radius: var(--radius-sm);\n    font-size: 12px;\n    font-weight: 600;\n    background: var(--green);\n    color: #000000;\n    margin-top: 5px;\n    transition: filter 0.15s ease;\n  }\n\n  .chart-action:hover {\n    filter: brightness(1.08);\n  }\n\n  .chart-action.sell {\n    background: var(--red);\n    color: #ffffff;\n  }\n\n  /* 深度委託簿 */\n  .book-container {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-lg);\n    padding: 18px;\n    margin-bottom: 18px;\n    overflow: hidden;\n    width: 100%;\n  }\n\n  .book-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 12px;\n  }\n\n  .book-header h3 {\n    font-size: 15px;\n    font-weight: 600;\n    color: #ffffff;\n  }\n\n  .book-content {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 12px;\n    width: 100%;\n  }\n\n  .book-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 12.5px;\n  }\n\n  .book-table th, .book-table td {\n    padding: 5px 8px;\n    text-align: right;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .book-table th:first-child, .book-table td:first-child {\n    text-align: left;\n  }\n\n  .book-bar {\n    position: relative;\n  }\n\n  .book-bar-fill {\n    position: absolute;\n    top: 0;\n    bottom: 0;\n    opacity: 0.14;\n    border-radius: 4px;\n    pointer-events: none;\n  }\n\n  .book-bar-fill.bid {\n    right: 0;\n    background: var(--green);\n  }\n\n  .book-bar-fill.ask {\n    left: 0;\n    background: var(--red);\n  }\n\n  /* 表格 - Apple 清爽條列 */\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n  }\n\n  th, td {\n    padding: 10px 12px;\n    border-bottom: 1px solid var(--line);\n    vertical-align: middle;\n  }\n\n  th {\n    font-size: 11.5px;\n    font-weight: 500;\n    color: var(--text-muted);\n    text-align: left;\n  }\n\n  td.num, th.num {\n    text-align: right;\n    font-variant-numeric: tabular-nums;\n  }\n\n  tr:hover td {\n    background: rgba(255, 255, 255, 0.02);\n  }\n\n  .table-wrap {\n    overflow-x: auto;\n    border-radius: var(--radius-md);\n    width: 100%;\n    max-width: 100%;\n  }\n\n  /* 按鈕 - Apple 原生觸感 */\n  button {\n    font-family: inherit;\n    cursor: pointer;\n    border: none;\n    border-radius: 9px;\n    font-weight: 600;\n    transition: all 0.16s var(--apple-ease);\n  }\n\n  button:active {\n    transform: scale(0.97);\n  }\n\n  button:disabled {\n    opacity: 0.45;\n    cursor: not-allowed;\n    transform: none !important;\n  }\n\n  .buy {\n    background: var(--green);\n    color: #000000;\n    padding: 6px 14px;\n    font-size: 13px;\n  }\n\n  .buy:hover:not(:disabled) {\n    filter: brightness(1.08);\n  }\n\n  .sell {\n    background: var(--red);\n    color: #ffffff;\n    padding: 6px 14px;\n    font-size: 13px;\n  }\n\n  .sell:hover:not(:disabled) {\n    filter: brightness(1.08);\n  }\n\n  .tag {\n    display: inline-block;\n    padding: 2px 6px;\n    border-radius: 5px;\n    font-size: 11px;\n    font-weight: 600;\n  }\n\n  .tag.BUY {\n    background: var(--green-bg);\n    color: var(--green);\n  }\n\n  .tag.SELL {\n    background: var(--red-bg);\n    color: var(--red);\n  }\n\n  .pos {\n    color: var(--green);\n  }\n\n  .neg {\n    color: var(--red);\n  }\n\n  /* 登入／訪客註冊卡片 - Apple ID 典雅風格 */\n  #auth-panel {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-lg);\n    padding: 32px 24px;\n    max-width: 400px;\n    margin: 30px auto;\n    text-align: center;\n    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4);\n    width: 100%;\n  }\n\n  .guest-hero-btn {\n    width: 100%;\n    padding: 12px;\n    background: #ffffff;\n    color: #000000;\n    font-size: 14.5px;\n    font-weight: 600;\n    border-radius: 11px;\n    margin-bottom: 18px;\n    transition: all 0.18s var(--apple-ease);\n  }\n\n  .guest-hero-btn:hover {\n    background: #e5e5e7;\n    transform: translateY(-1px);\n  }\n\n  .auth-divider {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    font-size: 11.5px;\n    color: var(--text-dim);\n    margin: 16px 0;\n  }\n\n  .auth-divider::before, .auth-divider::after {\n    content: '';\n    flex: 1;\n    height: 1px;\n    background: var(--line);\n  }\n\n  #auth-form label {\n    display: block;\n    text-align: left;\n    font-size: 12px;\n    font-weight: 500;\n    color: var(--text-muted);\n    margin: 10px 0 4px;\n  }\n\n  #auth-form input, dialog input, dialog select {\n    width: 100%;\n    background: #2c2c2e;\n    border: 1px solid rgba(255, 255, 255, 0.08);\n    border-radius: 9px;\n    padding: 10px 12px;\n    color: #ffffff;\n    font-size: 14px;\n    font-family: inherit;\n    outline: none;\n    transition: border-color 0.15s ease, box-shadow 0.15s ease;\n  }\n\n  #auth-form input:focus, dialog input:focus, dialog select:focus {\n    border-color: var(--blue);\n    box-shadow: 0 0 0 3px rgba(10, 132, 255, 0.25);\n  }\n\n  .auth-actions {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 10px;\n    margin-top: 16px;\n  }\n\n  /* 對話框 - Apple Sheet 圓角卡片 */\n  dialog {\n    border: 1px solid rgba(255, 255, 255, 0.12);\n    background: #1c1c1e;\n    border-radius: 18px;\n    padding: 22px;\n    max-width: 420px;\n    width: 92%;\n    color: #ffffff;\n    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.7);\n    margin: auto;\n  }\n\n  dialog::backdrop {\n    background: rgba(0, 0, 0, 0.65);\n    backdrop-filter: blur(14px);\n    -webkit-backdrop-filter: blur(14px);\n  }\n\n  dialog h3 {\n    font-size: 17px;\n    font-weight: 700;\n    margin-bottom: 6px;\n    color: #ffffff;\n    letter-spacing: -0.02em;\n  }\n\n  dialog label {\n    display: block;\n    font-size: 12px;\n    font-weight: 500;\n    color: var(--text-muted);\n    margin: 10px 0 4px;\n  }\n\n  .quick-chips {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 6px;\n    margin-top: 8px;\n  }\n\n  .quick-chip {\n    padding: 6px 0;\n    background: #2c2c2e;\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    color: var(--text);\n    font-size: 12px;\n    font-weight: 600;\n  }\n\n  .quick-chip:hover {\n    background: #3a3a3c;\n  }\n\n  .quick-chip.all-in {\n    color: var(--gold);\n    border-color: rgba(255, 159, 10, 0.3);\n  }\n\n  #trade-summary {\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 10px 12px;\n    margin: 12px 0;\n    font-size: 12.5px;\n  }\n\n  .summary-row {\n    display: flex;\n    justify-content: space-between;\n    margin: 4px 0;\n  }\n\n  .summary-row span:first-child {\n    color: var(--text-muted);\n  }\n\n  .dialog-actions {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 10px;\n    margin-top: 16px;\n  }\n\n  .dialog-actions button {\n    padding: 10px;\n    font-size: 13.5px;\n    border-radius: 9px;\n  }\n\n  .dialog-error {\n    color: var(--red);\n    font-size: 12px;\n    font-weight: 500;\n    margin-top: 6px;\n    min-height: 16px;\n  }\n\n  /* 提示彈窗 (Toast) - Apple Dynamic Island / Floating Capsule 風格 */\n  #msg {\n    position: fixed;\n    top: 20px;\n    left: 50%;\n    transform: translateX(-50%) translateY(-20px) scale(0.95);\n    background: rgba(28, 28, 30, 0.94);\n    backdrop-filter: blur(25px);\n    -webkit-backdrop-filter: blur(25px);\n    border: 1px solid rgba(255, 255, 255, 0.14);\n    border-radius: var(--radius-full);\n    padding: 9px 20px;\n    font-size: 13px;\n    font-weight: 600;\n    color: #ffffff;\n    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.6);\n    opacity: 0;\n    pointer-events: none;\n    transition: all 0.28s var(--apple-ease);\n    z-index: 1000;\n    max-width: 90vw;\n    text-align: center;\n  }\n\n  #msg.show {\n    opacity: 1;\n    transform: translateX(-50%) translateY(0) scale(1);\n  }\n\n  #msg.ok {\n    border-color: rgba(48, 209, 88, 0.35);\n  }\n\n  #msg.err {\n    border-color: rgba(255, 69, 58, 0.35);\n  }\n\n  /* 狂暴槓桿按鈕 - Apple Pro 簡約開關風格 */\n  .btn-turbo {\n    width: 100%;\n    margin-top: 10px;\n    padding: 8px;\n    background: rgba(255, 159, 10, 0.1);\n    border: 1px solid rgba(255, 159, 10, 0.25);\n    color: var(--gold);\n    border-radius: 9px;\n    font-size: 12px;\n    font-weight: 600;\n    cursor: pointer;\n    transition: all 0.2s var(--apple-ease);\n  }\n\n  .btn-turbo.active {\n    background: var(--gold);\n    color: #000000;\n    border-color: var(--gold);\n  }\n\n  .trade-dialog-turbo {\n    border-color: rgba(255, 159, 10, 0.35);\n  }\n\n  /* 觸感微脈衝 (替代原本晃動劇烈的屏幕震動) */\n  .whale-shaking {\n    animation: apple-haptic-pulse 0.35s var(--apple-ease);\n  }\n\n  @keyframes apple-haptic-pulse {\n    0% { transform: scale(1); }\n    50% { transform: scale(1.004); }\n    100% { transform: scale(1); }\n  }\n\n  /* 指數小卡 */\n  .index-card {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 12px 16px;\n    margin-bottom: 18px;\n    width: 100%;\n    text-align: left;\n    color: var(--text);\n  }\n\n  .index-card:hover {\n    background: var(--card-hover);\n  }\n\n  .index-label {\n    font-size: 13.5px;\n    font-weight: 600;\n    color: #ffffff;\n  }\n\n  .index-label small {\n    font-size: 11.5px;\n    color: var(--text-muted);\n    margin-left: 5px;\n    font-weight: normal;\n  }\n\n  .index-card strong {\n    font-size: 16px;\n    font-weight: 700;\n    margin-right: 8px;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .index-hint {\n    font-size: 11.5px;\n    color: var(--blue);\n  }\n\n  .index-details {\n    background: var(--card);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-md);\n    padding: 14px;\n    margin-bottom: 18px;\n    font-size: 12.5px;\n    color: var(--text-muted);\n    width: 100%;\n  }\n\n  .index-row, .fill-row {\n    display: flex;\n    justify-content: space-between;\n    padding: 6px 0;\n    border-bottom: 1px solid var(--line);\n    font-size: 12px;\n  }\n\n  .stock-detail-toggle {\n    background: transparent;\n    border: 1px solid var(--line);\n    color: var(--blue);\n    font-size: 11.5px;\n    padding: 3px 8px;\n    border-radius: 6px;\n    margin-top: 5px;\n  }\n\n  .stock-fills {\n    margin-top: 8px;\n    padding-top: 6px;\n    border-top: 1px solid var(--line);\n    font-size: 11.5px;\n    color: var(--text-muted);\n  }\n\n  #data-status {\n    padding: 8px 14px;\n    background: rgba(255, 69, 58, 0.12);\n    border: 1px solid rgba(255, 69, 58, 0.25);\n    border-radius: var(--radius-md);\n    color: var(--red);\n    font-size: 12.5px;\n    margin-bottom: 14px;\n  }\n\n  .empty {\n    text-align: center;\n    color: var(--text-muted);\n    padding: 20px;\n    font-size: 13px;\n  }\n\n  \n  /* Robinhood 24-Hour Time Horizon Selector */\n  .chart-time-selector {\n    display: flex;\n    gap: 6px;\n    margin: 10px 0 14px;\n    background: rgba(255, 255, 255, 0.04);\n    padding: 3px;\n    border-radius: var(--radius-sm);\n    width: fit-content;\n    border: 1px solid var(--line);\n  }\n  .time-tab {\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    font-size: 11.5px;\n    font-weight: 600;\n    padding: 5px 12px;\n    border-radius: 6px;\n    cursor: pointer;\n    transition: all 0.2s var(--apple-ease);\n  }\n  .time-tab.active {\n    background: var(--card-hover);\n    color: var(--text);\n    box-shadow: 0 1px 4px rgba(0,0,0,0.3);\n  }\n  .time-tab:hover:not(.active) {\n    color: var(--text);\n  }\n\n  /* Robinhood 下單模式切換 (依股數 vs 依金額) */\n  .trade-unit-selector {\n    display: flex;\n    background: rgba(255, 255, 255, 0.05);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-sm);\n    padding: 3px;\n    gap: 4px;\n    margin-bottom: 12px;\n  }\n  .trade-unit-btn {\n    flex: 1;\n    background: transparent;\n    border: none;\n    color: var(--text-muted);\n    font-size: 12px;\n    font-weight: 600;\n    padding: 6px 10px;\n    border-radius: 6px;\n    cursor: pointer;\n    transition: all 0.18s var(--apple-ease);\n    min-height: 36px;\n  }\n  .trade-unit-btn.active {\n    background: var(--card-hover);\n    color: var(--text);\n  }\n\n  /* Robinhood 白話訂單指引 */\n  .trade-explainer {\n    font-size: 11.5px;\n    color: var(--text-muted);\n    line-height: 1.4;\n    margin: -4px 0 12px;\n    padding: 6px 10px;\n    background: rgba(255, 255, 255, 0.03);\n    border-radius: 6px;\n    border-left: 2.5px solid var(--blue);\n  }\n\n  /* Robinhood 購買力指示條 */\n  .buying-power-pill {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background: rgba(255, 255, 255, 0.03);\n    border: 1px solid var(--line);\n    border-radius: var(--radius-sm);\n    padding: 8px 12px;\n    margin-bottom: 12px;\n    font-size: 12px;\n    color: var(--text-muted);\n  }\n  .buying-power-val {\n    color: var(--text);\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n  }\n\n  /* Robinhood 觸感滑動確認下單 (Slide to Confirm) */\n  .swipe-track {\n    position: relative;\n    width: 100%;\n    height: 48px;\n    background: rgba(255, 255, 255, 0.06);\n    border: 1px solid var(--line-light);\n    border-radius: var(--radius-full);\n    overflow: hidden;\n    user-select: none;\n    touch-action: none;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    margin: 8px 0 4px;\n    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.35);\n  }\n  .swipe-fill {\n    position: absolute;\n    left: 0;\n    top: 0;\n    bottom: 0;\n    width: 0%;\n    background: linear-gradient(90deg, rgba(0, 214, 116, 0.25), rgba(0, 214, 116, 0.55));\n    border-radius: var(--radius-full);\n    pointer-events: none;\n    transition: width 0.05s ease;\n  }\n  .swipe-track.sell-mode .swipe-fill {\n    background: linear-gradient(90deg, rgba(255, 59, 92, 0.25), rgba(255, 59, 92, 0.55));\n  }\n  .swipe-text {\n    position: relative;\n    z-index: 2;\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--text-muted);\n    letter-spacing: 0.02em;\n    pointer-events: none;\n    transition: opacity 0.2s;\n  }\n  .swipe-thumb {\n    position: absolute;\n    left: 4px;\n    top: 4px;\n    width: 40px;\n    height: 40px;\n    background: var(--astryx-bull-green);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #000000;\n    font-weight: 900;\n    font-size: 15px;\n    box-shadow: 0 2px 10px rgba(0, 214, 116, 0.5);\n    cursor: grab;\n    z-index: 3;\n    transition: transform 0.05s linear;\n  }\n  .swipe-track.sell-mode .swipe-thumb {\n    background: var(--astryx-bear-red);\n    box-shadow: 0 2px 10px rgba(255, 59, 92, 0.5);\n    color: #ffffff;\n  }\n  .swipe-thumb:active {\n    cursor: grabbing;\n    transform: scale(1.08);\n  }\n\n  /* 針對 640px 以下手機螢幕與 320px 極限螢幕的 Apple 原生響應式 */\n  @media(max-width: 640px) {\n    .site-header {\n      flex-direction: column;\n      align-items: stretch;\n      gap: 10px;\n      padding: 10px 12px;\n      margin: 0 0 14px;\n      width: 100%;\n    }\n    .user-badge-bar {\n      width: 100%;\n      justify-content: flex-start;\n      gap: 5px;\n    }\n    .navigation {\n      width: 100%;\n      overflow-x: auto;\n      scrollbar-width: none;\n      -webkit-overflow-scrolling: touch;\n      display: flex;\n    }\n    .navigation button {\n      padding: 6px 12px;\n      font-size: 12.5px;\n      flex-shrink: 0;\n    }\n    .portfolio-hero {\n      padding: 16px;\n    }\n    .portfolio-hero .val-big {\n      font-size: 26px;\n      gap: 8px;\n    }\n    .cards {\n      grid-template-columns: 1fr 1fr;\n      gap: 8px;\n    }\n    .hero-stock-box {\n      padding: 16px;\n    }\n    .hero-stock-head {\n      flex-direction: column;\n      gap: 12px;\n    }\n    .hero-stock-head > div:last-child {\n      width: 100%;\n      display: flex;\n      gap: 8px;\n    }\n    .hero-stock-head > div:last-child button {\n      flex: 1;\n    }\n    .book-content {\n      grid-template-columns: 1fr;\n    }\n    .chart-grid {\n      grid-template-columns: 1fr;\n    }\n    table {\n      font-size: 12px;\n    }\n    th, td {\n      padding: 8px 6px;\n    }\n  }\n\n  @media(prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n      animation-duration: 0.01ms !important;\n      animation-iteration-count: 1 !important;\n      transition-duration: 0.01ms !important;\n    }\n  }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header class=\"site-header\">\n    <div class=\"brand-group\">\n      <span class=\"brand-mark\" aria-hidden=\"true\">⚡</span>\n      <div>\n        <h1>小市場</h1>\n        <div class=\"brand-caption\">即時撮合模擬交易</div>\n      </div>\n    </div>\n    <div id=\"user-controls\" class=\"user-badge-bar\" hidden>\n      <span class=\"whale-chip\">● <span id=\"username-display\">模擬帳戶</span></span>\n      <button type=\"button\" class=\"recharge-btn\" id=\"btn-recharge\" title=\"補充千萬籌碼\">重設資金</button>\n      <button type=\"button\" class=\"sound-btn\" id=\"btn-sound\">靜音</button>\n      <button type=\"button\" id=\"logout\">登出</button>\n    </div>\n  </header>\n\n  <!-- 賭場跑馬燈 -->\n  <div class=\"ticker-marquee\" id=\"market-marquee\">\n    <span class=\"ticker-badge\">市場快訊</span>\n    <span class=\"ticker-text\" id=\"marquee-text\">市場撮合引擎運行中 · 機器人造市商即時掛單中...</span>\n  </div>\n\n  <div id=\"data-status\" hidden></div>\n\n  <!-- 未登入畫面 -->\n  <div id=\"auth-panel\">\n    <div style=\"font-size:40px; margin-bottom:12px;\">✦</div>\n    <h2 style=\"margin:0 0 8px; font-size:22px; font-weight:800; color:#fff;\">你的模擬交易場</h2>\n    <p style=\"color:var(--text-muted); font-size:13.5px; margin:0 0 20px; line-height:1.5;\">\n      六檔股票，即時模擬交易<br>\n      無需複雜註冊，一鍵進場領取 <strong>$10,000,000</strong> 操盤金！\n    </p>\n    <button type=\"button\" class=\"guest-hero-btn\" id=\"btn-guest-login\">一鍵開始交易</button>\n    \n    <div class=\"auth-divider\">或使用既有帳號登入</div>\n    \n    <form id=\"auth-form\" onsubmit=\"return false;\">\n      <label for=\"username\">使用者名稱</label>\n      <input id=\"username\" autocomplete=\"username\" placeholder=\"請輸入帳號 (3-24 字元)\">\n      <label for=\"password\">密碼</label>\n      <input id=\"password\" type=\"password\" autocomplete=\"current-password\" placeholder=\"請輸入密碼 (8 字元以上)\">\n      <div class=\"auth-actions\">\n        <button type=\"button\" class=\"buy\" id=\"login\">登入</button>\n        <button type=\"button\" style=\"background:#20293d;\" id=\"register\">註冊</button>\n      </div>\n      <div id=\"auth-error\" class=\"dialog-error\" style=\"margin-top:12px;\"></div>\n    </form>\n  </div>\n\n  <!-- 登入後主操作面板 -->\n  <div id=\"app-panel\" hidden>\n\n    <!-- 總資產看板 -->\n    <div class=\"portfolio-hero\">\n      <div class=\"label\">淨資產總額</div>\n      <div class=\"val-big\">\n        <span id=\"total-assets\">$0</span>\n        <span id=\"pnl-badge\" class=\"pnl-badge pnl-up\">+0.00%</span>\n      </div>\n      <div class=\"cards\">\n        <div class=\"card\">\n          <div class=\"label\">可用現金</div>\n          <div class=\"value\" id=\"cash\">$0</div>\n        </div>\n        <div class=\"card\" hidden>\n          <div class=\"label\">凍結委託金</div>\n          <div class=\"value\" id=\"frozen-cash\">$0</div>\n        </div>\n        <div class=\"card\">\n          <div class=\"label\">股票總現值</div>\n          <div class=\"value\" id=\"stocks-value\">$0</div>\n        </div>\n        <div class=\"card\">\n          <div class=\"label\">可下單資金</div>\n          <div class=\"value\" id=\"available\">$0</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- 頁籤導航 -->\n    <nav class=\"navigation\">\n      <button type=\"button\" data-nav=\"market\" aria-current=\"page\">行情</button>\n      <button type=\"button\" data-nav=\"trade\">下單</button>\n      <button type=\"button\" data-nav=\"holdings\">我的資產</button>\n      <button type=\"button\" data-nav=\"ranking\">排行榜</button>\n    </nav>\n\n    <!-- 行情分頁 -->\n    <section id=\"page-market\">\n      <!-- 焦點股票 Hero 走勢圖 -->\n      \n      <!-- 突發黑天鵝與市場動態實時快訊 -->\n      <div id=\"market-news-ticker\" class=\"market-news-ticker\" onclick=\"onTickerClick()\">\n        <div class=\"ticker-tag\">⚡ 即時快訊</div>\n        <div id=\"ticker-text\" class=\"ticker-text\">載入即時市場快訊中...</div>\n        <div id=\"ticker-impact\" class=\"ticker-impact\">+4.8%</div>\n      </div>\n      <div class=\"hero-stock-box\">\n        <div class=\"hero-stock-head\">\n          <div>\n            <span class=\"hero-stock-title\" id=\"hero-title\">台積電</span>\n            <span class=\"hero-stock-sym\" id=\"hero-sym\">2330 · GG</span>\n            <div class=\"hero-stock-price\" id=\"hero-price\">$0</div>\n            <div style=\"display:flex; align-items:center; flex-wrap:wrap; gap:6px;\">\n              <div id=\"hero-pnl\" style=\"font-size:13px; font-weight:700; color:var(--green);\">▲ +0.00 (+0.00%)</div>\n              <span id=\"hero-momentum-badge\" class=\"momentum-badge\">⚡ 動能活躍 · 振幅 ±3.8%</span>\n            </div>\n          </div>\n          <div style=\"display:flex; gap:8px;\">\n            <button type=\"button\" class=\"buy\" id=\"hero-buy-btn\" style=\"padding:10px 20px; font-size:14px;\">⚡ 立即買進</button>\n            <button type=\"button\" class=\"sell\" id=\"hero-sell-btn\" style=\"padding:10px 20px; font-size:14px;\">立即賣出</button>\n          </div>\n        </div>\n        \n        \n        <div class=\"tug-of-war-box\" id=\"tug-of-war-box\">\n          <div class=\"tug-header\">\n            <span class=\"tug-bull\" id=\"tug-bull-text\">🟢 多頭買盤 50%</span>\n            <span class=\"tug-title\">盤口買賣力道</span>\n            <span class=\"tug-bear\" id=\"tug-bear-text\">50% 空頭賣盤 🔴</span>\n          </div>\n          <div class=\"tug-bar-track\">\n            <div class=\"tug-bull-fill\" id=\"tug-bull-fill\" style=\"width:50%;\"></div>\n            <div class=\"tug-bear-fill\" id=\"tug-bear-fill\" style=\"width:50%;\"></div>\n          </div>\n        </div>\n        <div class=\"chart-meta-bar\">\n          <span>幣別單位：新台幣 (TWD) · 走勢更新週期：3 秒撮合輪詢</span>\n          <span id=\"hero-stat-note\">24H 全時交易模式</span>\n        </div>\n        <div class=\"chart-time-selector\" id=\"chart-time-selector\">\n          <button type=\"button\" class=\"time-tab active\" data-span=\"1D\" onclick=\"setChartSpan('1D')\">1D 即時</button>\n          <button type=\"button\" class=\"time-tab\" data-span=\"1W\" onclick=\"setChartSpan('1W')\">1W 近週</button>\n          <button type=\"button\" class=\"time-tab\" data-span=\"1M\" onclick=\"setChartSpan('1M')\">1M 近月</button>\n          <button type=\"button\" class=\"time-tab\" data-span=\"24H\" onclick=\"setChartSpan('24H')\">24H 全天候</button>\n        </div>\n\n        <div class=\"hero-chart-container\" id=\"hero-chart-box\">\n          <div class=\"chart-scrubber-pill\" id=\"hero-scrub-pill\" hidden>\n            <span id=\"scrub-price\">$0.00</span>\n            <span id=\"scrub-change\" style=\"color:var(--green);\">+0.00%</span>\n            <span id=\"scrub-time\" style=\"color:var(--text-muted);\">14:00</span>\n          </div>\n          <svg id=\"hero-svg\" viewBox=\"0 0 800 240\" preserveAspectRatio=\"none\">\n            <polyline fill=\"none\" stroke=\"#78a990\" stroke-width=\"2.5\" points=\"20,120 780,120\"></polyline>\n          </svg>\n        </div>\n      </div>\n\n      <button type=\"button\" class=\"index-card\" id=\"index-toggle\" aria-expanded=\"false\" aria-controls=\"index-details\">\n  <span class=\"index-label\">市場指數 <small>六檔模擬股票</small></span>\n  <strong id=\"index-value\">--</strong><span id=\"index-change\">等待行情</span>\n  <span class=\"index-hint\">查看權重與近期成交 →</span>\n</button>\n<div id=\"index-details\" class=\"index-details\" hidden>\n  <p>基準 1,000 點；依固定權重計算各股票相對平盤的漲跌，並非真實市值加權指數。</p>\n  <svg id=\"index-chart\" viewBox=\"0 0 400 110\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"市場指數歷史走勢\"></svg><div id=\"index-chart-note\" class=\"chart-note\"></div><div id=\"index-weights\"></div><h3>近期成交</h3><div id=\"index-fills\"></div>\n</div>\n<h2 style=\"font-size:16px; margin:24px 0 12px; color:#fff;\">六檔股票</h2>\n      <div class=\"chart-grid\" id=\"charts-grid\">\n        <!-- 6 個走勢卡片容器由 loadCharts 填充 -->\n      </div>\n\n      <!-- 委託簿深度 -->\n      <div class=\"book-container\">\n        <div class=\"book-header\">\n          <h3>五檔委託簿深度盤口 (ORDER BOOK) · <span id=\"book-symbol-title\">2330 台積電</span></h3>\n          <span style=\"font-size:12px; color:var(--text-muted);\">造市商與即時撮合流</span>\n        </div>\n        <div class=\"table-wrap\" style=\"margin-bottom:0;\">\n          <table class=\"book-table\">\n            <thead>\n              <tr>\n                <th>買盤筆數</th>\n                <th class=\"num\">買量 (BID)</th>\n                <th class=\"num\" style=\"color:var(--green);\">買價</th>\n                <th class=\"num\" style=\"color:var(--red);\">賣價</th>\n                <th class=\"num\">賣量 (ASK)</th>\n                <th class=\"num\">賣盤筆數</th>\n              </tr>\n            </thead>\n            <tbody id=\"book\">\n              <!-- 5 檔深度 -->\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- 下單分頁 -->\n    <section id=\"page-trade\" hidden>\n      <h2 style=\"font-size:18px; margin:0 0 16px; color:#fff;\">⚡ 快速下單交易台</h2>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>股票</th>\n              \n              <th class=\"num\">現價</th>\n              <th class=\"num\">平盤價</th>\n              <th class=\"num\">今日漲跌</th>\n              <th style=\"text-align:right;\">快捷交易</th>\n            </tr>\n          </thead>\n          <tbody id=\"rows\">\n            <!-- 股票列表與買賣按鈕 -->\n          </tbody>\n        </table>\n      </div>\n\n      <h3 style=\"font-size:15px; margin:24px 0 12px; color:#fff;\">未成交限價委託單</h3>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>委託時間</th>\n              <th>股票</th>\n              <th>買賣</th>\n              <th class=\"num\">委託價</th>\n              <th class=\"num\">委託股數</th>\n              <th class=\"num\">已成交</th>\n              <th>狀態</th>\n              <th>操作</th>\n            </tr>\n          </thead>\n          <tbody id=\"orders\">\n            <!-- 掛單列表 -->\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- 我的資產分頁 -->\n    <section id=\"page-holdings\" hidden>\n      <h2 style=\"font-size:18px; margin:0 0 14px; color:#fff;\">庫存持股明細</h2>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>股票代號</th>\n              <th class=\"num\">持股總數</th>\n              <th class=\"num\">凍結中</th>\n              <th class=\"num\">現價</th>\n              <th class=\"num\">持股市值</th>\n              <th style=\"text-align:right;\">快速清倉</th>\n            </tr>\n          </thead>\n          <tbody id=\"holdings\">\n            <!-- 庫存列表 -->\n          </tbody>\n        </table>\n      </div>\n\n      <h3 style=\"font-size:15px; margin:28px 0 12px; color:#fff;\">成交歷史紀錄</h3>\n      <div style=\"display:flex; gap:10px; margin-bottom:12px; flex-wrap:wrap; align-items:center;\">\n        <select id=\"filter-side\" style=\"padding:8px 12px; background:#10141f; border:1px solid var(--line-light); color:#fff; border-radius:8px;\">\n          <option value=\"\">全部買賣</option>\n          <option value=\"BUY\">買進 (BUY)</option>\n          <option value=\"SELL\">賣出 (SELL)</option>\n        </select>\n        <button type=\"button\" id=\"filter-apply\" style=\"background:#20293d;\">套用篩選</button>\n      </div>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>成交時間</th>\n              <th>股票</th>\n              <th>類別</th>\n              <th class=\"num\">股數</th>\n              <th class=\"num\">價格</th>\n              <th class=\"num\">成交總額</th>\n              <th class=\"num\">手續費</th>\n            </tr>\n          </thead>\n          <tbody id=\"trades\">\n            <!-- 成交明細 -->\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- 排行榜分頁 -->\n    <section id=\"page-ranking\" hidden>\n      <h2 style=\"font-size:18px; margin:0 0 14px; color:#fff;\">排行榜</h2>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th style=\"width:60px;\">名次</th>\n              <th>玩家身分</th>\n              <th class=\"num\">總資產 (淨值)</th>\n              <th style=\"text-align:right;\">稱號</th>\n            </tr>\n          </thead>\n          <tbody id=\"ranking-rows\">\n            <!-- 排行榜明細 -->\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n  </div>\n\n</div>\n\n<!-- 下單 Dialog -->\n<dialog id=\"trade-dialog\" aria-labelledby=\"trade-title\">\n  <h3 id=\"trade-title\">下單交易</h3>\n  <form id=\"trade-form\" onsubmit=\"return false;\">\n    <div class=\"buying-power-pill\">\n      <span>可用購買力 (Buying Power)</span>\n      <span class=\"buying-power-val\" id=\"dialog-buying-power\">$0.00</span>\n    </div>\n\n    <div class=\"trade-unit-selector\">\n      <button type=\"button\" class=\"trade-unit-btn active\" id=\"trade-mode-shares\" onclick=\"setTradeUnitMode('SHARES')\">依股數下單 (Shares)</button>\n      <button type=\"button\" class=\"trade-unit-btn\" id=\"trade-mode-dollars\" onclick=\"setTradeUnitMode('DOLLARS')\">依金額下單 ($ Dollars)</button>\n    </div>\n\n    <label for=\"trade-type\">委託種類</label>\n    <select id=\"trade-type\">\n      <option value=\"MARKET\">市價單 (Market Order)</option>\n      <option value=\"LIMIT\">限價單 (Limit Order)</option>\n    </select>\n    <div id=\"trade-type-explainer\" class=\"trade-explainer\">市價單：以當前市場最優價格即時撮合，成交速度最快。</div>\n\n    <div id=\"dollar-input-field\" hidden>\n      <label for=\"trade-dollars\">投資預算 (新台幣 TWD)</label>\n      <input id=\"trade-dollars\" type=\"number\" min=\"1\" step=\"1\" placeholder=\"輸入投資金額，自動換算股數\">\n    </div>\n\n    <div id=\"shares-input-field\">\n      <label for=\"trade-shares\">交易股數</label>\n      <input id=\"trade-shares\" type=\"number\" min=\"1\" step=\"1\" placeholder=\"輸入股數\">\n    </div>\n    <div class=\"quick-chips\">\n      <button type=\"button\" class=\"quick-chip\" onclick=\"addShares(10)\">+10</button>\n      <button type=\"button\" class=\"quick-chip\" onclick=\"addShares(50)\">+50</button>\n      <button type=\"button\" class=\"quick-chip\" onclick=\"addShares(100)\">+100</button>\n      <button type=\"button\" class=\"quick-chip\" onclick=\"addShares(1000)\">+1,000 (巨鯨掃貨)</button>\n      <button type=\"button\" class=\"quick-chip all-in\" onclick=\"setQuickShares(1)\">全部投入</button>\n    </div>\n\n    <div id=\"price-field\" hidden>\n      <label for=\"trade-price\">每股限價</label>\n      <input id=\"trade-price\" type=\"number\" step=\"0.01\" placeholder=\"輸入限價\" aria-describedby=\"trade-price-range\">\n      <div id=\"trade-price-range\" class=\"chart-note\" aria-live=\"polite\"></div>\n    </div>\n\n    <div id=\"trade-summary\">\n      <!-- 動態計算摘要 -->\n    </div>\n\n    <div class=\"swipe-track\" id=\"swipe-track\">\n        <div class=\"swipe-fill\" id=\"swipe-fill\"></div>\n        <div class=\"swipe-thumb\" id=\"swipe-thumb\" role=\"slider\" aria-label=\"滑動確認下單\" tabindex=\"0\">➜</div>\n        <span class=\"swipe-text\" id=\"swipe-text\">滑動確認下單 ➜</span>\n      </div>\n      <div class=\"dialog-actions\">\n      <div id=\"trade-error\" class=\"dialog-error\" role=\"alert\"></div>\n      <button type=\"button\" class=\"buy\" id=\"confirm-trade\">確認買進</button>\n      <button type=\"button\" style=\"background:#20293d;\" id=\"cancel-trade\">取消</button>\n    </div>\n  </form>\n</dialog>\n\n<!-- 取消委託 Dialog -->\n<dialog id=\"cancel-dialog\">\n  <h3>確認取消委託？</h3>\n  <p style=\"font-size:13.5px; color:var(--text-muted);\">取消後凍結資金或持股將全數解凍還原至帳戶。</p>\n  <div class=\"dialog-actions\">\n    <button type=\"button\" class=\"sell\" id=\"confirm-cancel\">確認取消委託</button>\n    <button type=\"button\" style=\"background:#20293d;\" onclick=\"document.getElementById('cancel-dialog').close()\">返回</button>\n  </div>\n</dialog>\n\n<!-- 浮動提示 Toast -->\n<div id=\"msg\"></div>\n\n<script>\nvar signedIn = false;\nvar currentStocks = [];\nvar selectedSymbol = '2330';\nvar activeTradeSide = 'BUY';\nvar cancelOrderId = null;\nvar currentAccount = null;\nvar soundEnabled = false;\nvar isSubmitting = false;\nvar cachedHistories = {};\n\nvar AudioContextClass = window.AudioContext || window.webkitAudioContext;\nvar audioCtx = null;\nfunction getAudioCtx() {\n  if (!audioCtx && AudioContextClass) audioCtx = new AudioContextClass();\n  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();\n  return audioCtx;\n}\nfunction playTone(freq, type, duration, delay) {\n  if (!soundEnabled) return;\n  try {\n    var ctx = getAudioCtx();\n    if (!ctx) return;\n    var d = delay || 0;\n    var osc = ctx.createOscillator();\n    var gain = ctx.createGain();\n    osc.type = type;\n    osc.frequency.setValueAtTime(freq, ctx.currentTime + d);\n    gain.gain.setValueAtTime(0.12, ctx.currentTime + d);\n    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + d + duration);\n    osc.connect(gain);\n    gain.connect(ctx.destination);\n    osc.start(ctx.currentTime + d);\n    osc.stop(ctx.currentTime + d + duration);\n  } catch(e) {}\n}\nfunction playBuyChime() {\n  playTone(523.25, 'triangle', 0.12, 0);\n  playTone(659.25, 'triangle', 0.12, 0.08);\n  playTone(783.99, 'triangle', 0.18, 0.16);\n  playTone(1046.50, 'triangle', 0.25, 0.24);\n}\nfunction playSellChime() {\n  playTone(880, 'sine', 0.1, 0);\n  playTone(1174.66, 'sine', 0.2, 0.08);\n}\nfunction playWhaleBoom() {\n  playTone(110, 'sawtooth', 0.35, 0);\n  playTone(440, 'triangle', 0.2, 0.1);\n  playTone(880, 'sine', 0.3, 0.2);\n}\n\nfunction fmt(n) { return Number(n).toLocaleString('zh-TW', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }\nfunction fmtInt(n) { return Number(n).toLocaleString('zh-TW'); }\n\nfunction toast(text, ok) {\n  var isOk = (ok === undefined || ok === true);\n  var m = document.getElementById('msg');\n  m.textContent = text;\n  m.className = 'show ' + (isOk ? 'ok' : 'err');\n  setTimeout(function() { if (m.textContent === text) m.className = ''; }, 3200);\n}\n\ndocument.querySelectorAll('.navigation button').forEach(function(btn) {\n  btn.onclick = function() {\n    document.querySelectorAll('.navigation button').forEach(function(b) { b.removeAttribute('aria-current'); });\n    btn.setAttribute('aria-current', 'page');\n    var target = btn.dataset.nav;\n    ['market', 'trade', 'holdings', 'ranking'].forEach(function(p) {\n      var el = document.getElementById('page-' + p);\n      if (el) el.hidden = (p !== target);\n    });\n    if (target === 'ranking') loadLeaderboard();\n  };\n});\n\ndocument.getElementById('btn-sound').onclick = function() {\n  soundEnabled = !soundEnabled;\n  document.getElementById('btn-sound').textContent = soundEnabled ? '🔊 音效' : '靜音';\n};\n\ndocument.getElementById('btn-recharge').onclick = async function() {\n  try {\n    var res = await fetch('/api/account/recharge', { method: 'POST' });\n    var data = await res.json();\n    if (data.ok) {\n      toast('💰 成功補滿千萬籌碼！隨時狂熱下單！', true);\n      playBuyChime();\n      pollLive();\n    }\n  } catch(e) {}\n};\n\ndocument.getElementById('btn-guest-login').onclick = async function() {\n  if (this.disabled) return;\n  this.disabled = true;\n  try {\n    var res = await fetch('/api/auth/guest', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ nickname: '大戶' })\n    });\n    var data = await res.json();\n    if (data.ok) {\n      toast('歡迎進入小市場', true);\n      playWhaleBoom();\n      await refreshSession();\n    } else {\n      document.getElementById('auth-error').textContent = data.message || '進場失敗';\n    }\n  } catch(e) {\n    document.getElementById('auth-error').textContent = '網路異常，請稍後再試';\n  } finally { this.disabled = false; }\n};\n\ndocument.getElementById('login').onclick = function() { authAction('login'); };\ndocument.getElementById('register').onclick = function() { authAction('register'); };\ndocument.getElementById('logout').onclick = async function() {\n  await fetch('/api/auth/logout', { method: 'POST' });\n  location.reload();\n};\n\nasync function authAction(action) {\n  var u = document.getElementById('username').value.trim();\n  var p = document.getElementById('password').value;\n  var errEl = document.getElementById('auth-error');\n  errEl.textContent = '';\n  if (!u || !p) { errEl.textContent = '請輸入帳號與密碼'; return; }\n  try {\n    var res = await fetch('/api/auth/' + action, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ username: u, password: p })\n    });\n    var data = await res.json();\n    if (data.ok) {\n      if (action === 'register') {\n        errEl.textContent = '註冊成功，請點擊登入';\n      } else {\n        await refreshSession();\n      }\n    } else {\n      errEl.textContent = data.message || (action === 'register' ? '註冊失敗' : '帳號或密碼錯誤');\n    }\n  } catch(e) {\n    errEl.textContent = '伺服器連線失敗';\n  }\n}\n\nasync function refreshSession() {\n  try {\n    var res = await fetch('/api/auth/session');\n    if (res.ok) {\n      var data = await res.json();\n      signedIn = true;\n      document.getElementById('auth-panel').hidden = true;\n      document.getElementById('app-panel').hidden = false;\n      document.getElementById('user-controls').hidden = false;\n      document.getElementById('username-display').textContent = data.username || '大戶玩家';\n      await pollLive();\n    } else {\n      signedIn = false;\n      document.getElementById('auth-panel').hidden = false;\n      document.getElementById('app-panel').hidden = true;\n      document.getElementById('user-controls').hidden = true;\n    }\n  } catch(e) {\n    var statusEl = document.getElementById(signedIn ? 'data-status' : 'auth-error');\n    if (statusEl) {\n      statusEl.textContent = '資料更新失敗，請檢查網路並重新整理';\n      statusEl.hidden = false;\n    }\n  }\n}\n\n// 高效整合輪詢：單一請求一次取回所有數據，降低 Cloudflare 請求數 85%\nasync function fetchWithTimeout(url) {\n  var controller = new AbortController();\n  var timer = setTimeout(function(){controller.abort();}, 15000);\n  try {\n    var response=await fetch(url, {signal:controller.signal});\n    if(!response.ok){controller.abort();return {ok:false,status:response.status};}\n    var body=await response.text();\n    return {ok:response.ok, status:response.status, json:function(){return Promise.resolve(JSON.parse(body));}};\n  } finally { clearTimeout(timer); }\n}\nvar appliedTradeSide = '';\nvar refreshSequence = 0;\nasync function pollLive() {\n  if (!signedIn) return;\n  var sequence=++refreshSequence;\n  try {\n    var res = await fetchWithTimeout('/api/live?symbol=' + encodeURIComponent(selectedSymbol) + '&trade_side=' + encodeURIComponent(appliedTradeSide));\n    if (sequence!==refreshSequence) return;\n    if (!res.ok) {\n      // Fallback to individual endpoints if /api/live is not available\n      return load();\n    }\n    var data = await res.json();\n    if (sequence!==refreshSequence) return;\n    document.getElementById('data-status').hidden=true;\n    currentStocks = data.stocks || [];\n    cachedHistories = data.histories || {};\n\n    if (data.account) {\n      currentAccount = { account: data.account, holdings: data.holdings || [] };\n      renderAccount(currentAccount);\n      renderHoldings(data.holdings || []);\n      renderOrders(data.orders || []);\n      renderTrades(data.trades || []);\n    }\n    renderStocks(currentStocks);\n    marketFillsAvailable=Array.isArray(data.fills);\n    renderMarketIndex(currentStocks, marketFillsAvailable ? data.fills : []);\n    renderHeroStock();\n    renderBook(data.bids || [], data.asks || []);\n    if (data.events) renderNewsTicker(data.events);\n    updateTugOfWar(data.bids || [], data.asks || []);\n    renderHeroChart(cachedHistories[selectedSymbol] || []);\n    renderChartsGrid();\n    if(document.getElementById('trade-dialog').open) updateTradeSummary();\n    if (Array.isArray(data.fills)) renderMarquee(data.fills);\n  } catch(e) {\n    if (sequence!==refreshSequence) return;\n    document.getElementById('data-status').textContent = '更新失敗，請檢查網路連線';\n    document.getElementById('data-status').hidden = false;\n  }\n}\n\nasync function load() {\n  if (!signedIn) return;\n  var sequence=++refreshSequence;\n  try {\n    var results = await Promise.all([\n      fetchWithTimeout('/api/stocks'),\n      fetchWithTimeout('/api/account'),\n      fetchWithTimeout('/api/trades?limit=30&side=' + encodeURIComponent(appliedTradeSide)),\n      fetchWithTimeout('/api/orders'),\n      fetchWithTimeout('/api/histories'),\n      fetchWithTimeout('/api/market-activity').catch(function(){return {ok:false};})\n    ]);\n    if(results.slice(0,5).some(function(response){return !response.ok;})) throw new Error('資料載入失敗');\n    var stocksData = await results[0].json();\n    var accData = await results[1].json();\n    var tradesData = await results[2].json();\n    var ordersData = await results[3].json();\n    var histData = await results[4].json();\n    var activityData = null;\n    if(results[5].ok) { try { activityData = await results[5].json(); } catch(e) {} }\n\n    if (sequence!==refreshSequence) return;\n    document.getElementById('data-status').hidden=true;\n    currentStocks = stocksData.stocks || [];\n    currentAccount = accData;\n    cachedHistories = histData.histories || {};\n\n    renderAccount(accData);\n    renderStocks(currentStocks);\n    marketFillsAvailable=!!activityData && Array.isArray(activityData.fills);\n    renderMarketIndex(currentStocks, marketFillsAvailable ? activityData.fills : []);\n    renderOrders(ordersData.orders || []);\n    renderHoldings(accData.holdings || []);\n    renderTrades(tradesData.trades || []);\n    renderHeroStock();\n    renderHeroChart(cachedHistories[selectedSymbol] || []);\n    renderChartsGrid();\n    if(document.getElementById('trade-dialog').open) updateTradeSummary();\n  } catch(e) {\n    if (sequence!==refreshSequence) return;\n    document.getElementById('data-status').textContent = '更新失敗，請檢查網路連線';\n    document.getElementById('data-status').hidden = false;\n  }\n}\n\nvar marketFillsAvailable = true;\nvar recentMarketFills = [];\nvar expandedStock = null;\nvar indexWeights = {'2330':.30,'2454':.20,'2317':.18,'3711':.14,'YZU':.10,'YOUJIAN':.08};\ndocument.getElementById('index-toggle').onclick = function() {\n  var details=document.getElementById('index-details');\n  details.hidden=!details.hidden;\n  this.setAttribute('aria-expanded', String(!details.hidden));\n};\nfunction renderMarketIndex(stocks, fills) {\n  recentMarketFills = fills;\n  if(stocks.length!==6 || stocks.some(function(s){return !s.ref_price || !indexWeights[s.symbol];})) { document.getElementById('index-value').textContent='--'; document.getElementById('index-change').textContent='行情資料不足'; clearChartInteraction(document.getElementById('index-chart')); document.getElementById('index-chart-note').textContent='行情資料不足'; document.getElementById('index-weights').replaceChildren(); document.getElementById('index-fills').textContent='行情資料不足'; return; }\n  var change=stocks.reduce(function(sum,s){return sum+indexWeights[s.symbol]*(s.price/s.ref_price-1);},0);\n  document.getElementById('index-value').textContent=fmt(1000*(1+change));\n  document.getElementById('index-change').textContent=(change>=0?'+':'')+(change*100).toFixed(2)+'%';\n  renderIndexHistory(stocks);\n  var weights=document.getElementById('index-weights'); weights.replaceChildren();\n  stocks.forEach(function(s){var row=document.createElement('div');row.className='index-row';var a=document.createElement('span'),b=document.createElement('span');a.textContent=s.nickname||s.name;b.textContent=(indexWeights[s.symbol]*100).toFixed(0)+'%';row.append(a,b);weights.appendChild(row);});\n  var box=document.getElementById('index-fills');box.replaceChildren();\n  if(!fills.length){box.textContent=marketFillsAvailable?'目前沒有成交紀錄':'近期成交資料暫時無法取得';return;}\n  fills.forEach(function(f){var row=document.createElement('div');row.className='fill-row';row.textContent=formatFillTime(f.created_at)+' · '+(f.nickname||f.stock_name)+' · '+f.buyer_name+(f.buyer_is_bot?'（機器人）':'')+' 買進 '+fmtInt(f.shares)+' 股；'+f.seller_name+(f.seller_is_bot?'（機器人）':'')+' 賣出 '+fmtInt(f.shares)+' 股 · '+fmt(f.price)+' 元';box.appendChild(row);});\n}\nfunction renderMarquee(fills) {\n  if (!fills || !fills.length) return;\n  var recent = fills[0];\n  var isWhale = recent.shares >= 50;\n  var tag = isWhale ? '🚨 巨鯨出沒' : '⚡ 最新撮合';\n  var text = tag + ' · ' + (recent.nickname || recent.stock_name) + ' 成交 ' + fmtInt(recent.shares) + ' 股 @ $' + fmt(recent.price) + ' (' + recent.buyer_name + ' 買進)';\n  var el = document.getElementById('marquee-text');\n  if (el.textContent !== text) {\n    el.style.opacity = 0;\n    setTimeout(function() { el.textContent = text; el.style.opacity = 1; }, 200);\n  }\n}\n\nfunction renderAccount(data) {\n  var acc = data.account;\n  var holdings = data.holdings || [];\n  var incomplete=holdings.some(function(h){return h.shares>0&&!currentStocks.some(function(s){return s.symbol===h.symbol && Number.isFinite(Number(s.price)) && Number(s.price)>0;});});\n  var stocksVal = holdings.reduce(function(sum, h) {\n    var s = currentStocks.find(function(x) { return x.symbol === h.symbol; });\n    return sum + (s ? s.price * h.shares : 0);\n  }, 0);\n  var total = Number(acc.cash) + stocksVal;\n  var init = Number(acc.initial_cash || 10000000);\n  var pnlRate = ((total - init) / init * 100);\n\n  document.getElementById('total-assets').textContent = incomplete ? '行情資料不足' : '$' + fmt(total);\n  document.getElementById('cash').textContent = '$' + fmt(acc.cash);\n  document.getElementById('frozen-cash').textContent = '$' + fmt(acc.frozen_cash || 0);\n  document.getElementById('stocks-value').textContent = incomplete ? '行情資料不足' : '$' + fmt(stocksVal);\n  var frozen = Number(acc.frozen_cash || 0);\n  var avail = Math.max(0, Number(acc.cash) - frozen);\n  document.getElementById('available').textContent = '$' + fmt(avail) + ' (凍結 ' + fmt(frozen) + ')';\n\n  var badge = document.getElementById('pnl-badge');\n  badge.textContent = incomplete ? '無法計算損益' : (pnlRate >= 0 ? '+' : '') + pnlRate.toFixed(2) + '% 獲利';\n  badge.className = incomplete ? 'pnl-badge' : 'pnl-badge ' + (pnlRate >= 0 ? 'pnl-up' : 'pnl-down');\n}\n\n\n// --- 破壞式創新模組：黑天鵝快訊、巨鯨震動、多空拔河與狂暴槓桿 ---\nvar currentEvents = [];\nvar activeTickerEvent = null;\nvar isTurbo = false;\n\nfunction triggerWhaleShake() {\n  document.body.classList.add('whale-shaking');\n  setTimeout(function() {\n    document.body.classList.remove('whale-shaking');\n  }, 450);\n}\n\nfunction toggleTurbo() {\n  isTurbo = !isTurbo;\n  var btn = document.getElementById('btn-turbo');\n  var dlg = document.getElementById('trade-dialog');\n  if (isTurbo) {\n    btn.textContent = '🔥 狂暴 5X 槓桿模式：已啟動 (盈虧放大 500%)';\n    btn.classList.add('active');\n    dlg.classList.add('trade-dialog-turbo');\n    playTone(587.33, 'sawtooth', 0.12);\n  } else {\n    btn.textContent = '⚡ 狂暴 5X 槓桿模式：未開啟';\n    btn.classList.remove('active');\n    dlg.classList.remove('trade-dialog-turbo');\n  }\n  updateTradeSummary();\n}\n\nfunction onTickerClick() {\n  if (activeTickerEvent && activeTickerEvent.symbol) {\n    selectStock(activeTickerEvent.symbol);\n    toast('已鎖定快訊標的：' + activeTickerEvent.symbol, true);\n  }\n}\n\nfunction renderNewsTicker(events) {\n  if (!events || !events.length) return;\n  currentEvents = events;\n  var evt = events[0];\n  activeTickerEvent = evt;\n  var txt = document.getElementById('ticker-text');\n  var imp = document.getElementById('ticker-impact');\n  if (txt && imp) {\n    txt.textContent = evt.title;\n    imp.textContent = evt.impact;\n    if (evt.impact && evt.impact.startsWith('-')) {\n      imp.className = 'ticker-impact neg';\n    } else {\n      imp.className = 'ticker-impact';\n    }\n  }\n}\n\nfunction updateTugOfWar(bids, asks) {\n  var totalBids = (bids || []).reduce(function(sum, b) { return sum + (Number(b.shares) || 0); }, 0);\n  var totalAsks = (asks || []).reduce(function(sum, a) { return sum + (Number(a.shares) || 0); }, 0);\n  var total = totalBids + totalAsks;\n  var bullPct = total > 0 ? Math.round(totalBids / total * 100) : 50;\n  var bearPct = 100 - bullPct;\n  var bullText = document.getElementById('tug-bull-text');\n  var bearText = document.getElementById('tug-bear-text');\n  var bullFill = document.getElementById('tug-bull-fill');\n  var bearFill = document.getElementById('tug-bear-fill');\n  if (bullText && bearText && bullFill && bearFill) {\n    bullText.textContent = '🟢 多頭買盤 ' + bullPct + '% (' + fmtInt(totalBids) + '股)';\n    bearText.textContent = bearPct + '% (' + fmtInt(totalAsks) + '股) 空頭賣盤 🔴';\n    bullFill.style.width = bullPct + '%';\n    bearFill.style.width = bearPct + '%';\n  }\n  var badge = document.getElementById('hero-momentum-badge');\n  if (badge) {\n    var amp = Math.abs(bullPct - 50) * 0.2 + 2.5;\n    var stateLabel = bullPct > 60 ? '🔥 多頭狂飆' : (bullPct < 40 ? '⚡ 空方摜壓' : '⚡ 激烈拔河');\n    badge.textContent = stateLabel + ' · 能量 ' + amp.toFixed(1) + '%';\n  }\n}\n\nfunction renderStocks(stocks) {\n  var tbody = document.getElementById('rows');\n  var focused=tbody.contains(document.activeElement) ? document.activeElement.getAttribute('onclick') : null;\n  tbody.innerHTML = '';\n  stocks.forEach(function(s) {\n    var tr = document.createElement('tr');\n    tr.id = 'stock-row-' + s.symbol;\n    var diff = s.price - (s.ref_price || s.price);\n    var pct = s.ref_price ? (diff / s.ref_price * 100) : 0;\n    var isUp = diff >= 0;\n\n    tr.innerHTML = '<td><strong>' + (s.nickname || s.name) + '</strong></td>' +\n      '<td class=\"num\"><strong>$' + fmt(s.price) + '</strong></td>' +\n      '<td class=\"num\" style=\"color:var(--text-muted);\">$' + fmt(s.ref_price || s.price) + '</td>' +\n      '<td class=\"num ' + (isUp ? 'pos' : 'neg') + '\">' + (isUp ? '+' : '') + fmt(diff) + ' (' + (isUp ? '+' : '') + pct.toFixed(2) + '%)</td>' +\n      '<td style=\"text-align:right;\">' +\n        '<button type=\"button\" class=\"buy\" onclick=\"openTrade(\\'' + s.symbol + '\\',\\'BUY\\')\">' + (s.nickname || s.name) + ' 買進</button> ' +\n        '<button type=\"button\" class=\"sell\" onclick=\"openTrade(\\'' + s.symbol + '\\',\\'SELL\\')\">' + (s.nickname || s.name) + ' 賣出</button>' +\n      '</td>';\n    tbody.appendChild(tr);\n  });\n  if(focused){var target=Array.from(tbody.querySelectorAll('button')).find(function(b){return b.getAttribute('onclick')===focused;});if(target)target.focus({preventScroll:true});}\n}\n\nfunction renderHeroStock() {\n  var stock = currentStocks.find(function(s) { return s.symbol === selectedSymbol; }) || currentStocks[0];\n  if (!stock) return;\n  selectedSymbol = stock.symbol;\n  document.getElementById('hero-title').textContent = stock.name;\n  document.getElementById('hero-sym').textContent = stock.symbol + ' · ' + (stock.nickname || '');\n  document.getElementById('hero-price').textContent = '$' + fmt(stock.price);\n  \n  var diff = stock.price - (stock.ref_price || stock.price);\n  var pct = stock.ref_price ? (diff / stock.ref_price * 100) : 0;\n  var isUp = diff >= 0;\n  var pnlEl = document.getElementById('hero-pnl');\n  pnlEl.textContent = (isUp ? '▲ +' : '▼ ') + fmt(diff) + ' (' + (isUp ? '+' : '') + pct.toFixed(2) + '%) 今日';\n  pnlEl.style.color = isUp ? 'var(--green)' : 'var(--red)';\n\n  document.getElementById('hero-buy-btn').onclick = function() { openTrade(stock.symbol, 'BUY'); };\n  document.getElementById('hero-sell-btn').onclick = function() { openTrade(stock.symbol, 'SELL'); };\n  document.getElementById('book-symbol-title').textContent = stock.symbol + ' ' + (stock.nickname || stock.name);\n}\n\nfunction renderOrders(orders) {\n  var tbody = document.getElementById('orders');\n  var focused=tbody.contains(document.activeElement) ? document.activeElement.getAttribute('onclick') : null;\n  tbody.innerHTML = '';\n  var openOrders = orders.filter(function(o) { return o.status === 'OPEN' || o.status === 'PARTIAL'; });\n  if (!openOrders.length) {\n    tbody.innerHTML = '<tr><td colspan=\"8\" class=\"empty\">目前無掛單中委託</td></tr>';\n    return;\n  }\n  openOrders.forEach(function(o) {\n    var s = currentStocks.find(function(x) { return x.symbol === o.symbol; });\n    var tr = document.createElement('tr');\n    tr.innerHTML = '<td>' + formatFillTime(o.created_at) + '</td>' +\n      '<td><strong>' + (s ? (s.nickname || s.name) : o.symbol) + '</strong></td>' +\n      '<td><span class=\"tag ' + o.side + '\">' + (o.side === 'BUY' ? '買進' : '賣出') + '</span></td>' +\n      '<td class=\"num\">$' + fmt(o.price) + '</td>' +\n      '<td class=\"num\">' + fmtInt(o.shares) + '</td>' +\n      '<td class=\"num\">' + fmtInt(o.filled_shares || 0) + '</td>' +\n      '<td><span style=\"color:var(--gold);\">等待成交</span></td>' +\n      '<td><button type=\"button\" style=\"background:#20293d;\" onclick=\"openCancel(' + o.id + ')\">取消</button></td>';\n    tbody.appendChild(tr);\n  });\n  if(focused){var target=Array.from(tbody.querySelectorAll('button')).find(function(b){return b.getAttribute('onclick')===focused;});if(target)target.focus({preventScroll:true});}\n}\n\nfunction renderHoldings(holdings) {\n  var tbody = document.getElementById('holdings');\n  var focused=tbody.contains(document.activeElement) ? document.activeElement.getAttribute('onclick') : null;\n  tbody.innerHTML = '';\n  var activeHoldings = holdings.filter(function(h) { return h.shares > 0; });\n  if (!activeHoldings.length) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"empty\">目前無任何股票庫存</td></tr>';\n    return;\n  }\n  activeHoldings.forEach(function(h) {\n    var s = currentStocks.find(function(x) { return x.symbol === h.symbol; });\n    var validPrice=s && Number.isFinite(Number(s.price)) && Number(s.price)>0;\n    var price = validPrice ? Number(s.price) : 0;\n    var mktVal = price * h.shares;\n    var tr = document.createElement('tr');\n    tr.innerHTML = '<td><strong>' + (s ? (s.nickname || s.name) : h.symbol) + '</strong></td>' +\n      '<td class=\"num\">' + fmtInt(h.shares) + '</td>' +\n      '<td class=\"num\" style=\"color:var(--text-muted);\">' + fmtInt(h.frozen_shares || 0) + '</td>' +\n      '<td class=\"num\">' + (validPrice ? '$' + fmt(price) : '行情不足') + '</td>' +\n      '<td class=\"num\"><strong>' + (validPrice ? '$' + fmt(mktVal) : '無法估值') + '</strong></td>' +\n      '<td style=\"text-align:right;\">' +\n        '<button type=\"button\" class=\"sell\" onclick=\"openTrade(\\'' + h.symbol + '\\',\\'SELL\\')\">快速賣出</button>' +\n      '</td>';\n    tbody.appendChild(tr);\n  });\n  if(focused){var target=Array.from(tbody.querySelectorAll('button')).find(function(b){return b.getAttribute('onclick')===focused;});if(target)target.focus({preventScroll:true});}\n}\n\nfunction renderTrades(trades) {\n  var tbody = document.getElementById('trades');\n  tbody.innerHTML = '';\n  var filter = appliedTradeSide;\n  var filtered = filter ? trades.filter(function(t) { return t.side === filter; }) : trades;\n  if (!filtered.length) {\n    tbody.innerHTML = '<tr><td colspan=\"7\" class=\"empty\">查無符合條件的成交明細</td></tr>';\n    return;\n  }\n  filtered.forEach(function(t) {\n    var s = currentStocks.find(function(x) { return x.symbol === t.symbol; });\n    var tr = document.createElement('tr');\n    tr.innerHTML = '<td>' + formatFillTime(t.created_at) + '</td>' +\n      '<td><strong>' + (s ? (s.nickname || s.name) : t.symbol) + '</strong></td>' +\n      '<td><span class=\"tag ' + t.side + '\">' + (t.side === 'BUY' ? '買進' : '賣出') + '</span></td>' +\n      '<td class=\"num\">' + fmtInt(t.shares) + '</td>' +\n      '<td class=\"num\">$' + fmt(t.price) + '</td>' +\n      '<td class=\"num\"><strong>$' + fmt(t.amount) + '</strong></td>' +\n      '<td class=\"num\" style=\"color:var(--text-muted); font-size:12px;\">$' + fmt(t.fee_amount || 0) + '</td>';\n    tbody.appendChild(tr);\n  });\n}\n\ndocument.getElementById('filter-apply').onclick = function() { appliedTradeSide=document.getElementById('filter-side').value; load(); };\n\nasync function loadLeaderboard() {\n  try {\n    var res = await fetch('/api/leaderboard');\n    if (!res.ok) return;\n    var data = await res.json();\n    var tbody = document.getElementById('ranking-rows');\n    tbody.innerHTML = '';\n    (data.players || []).forEach(function(p, idx) {\n      var tr = document.createElement('tr');\n      var isTop = idx === 0;\n      tr.innerHTML = '<td><strong style=\"color:' + (isTop ? 'var(--gold)' : 'var(--text-muted)') + '; font-size:15px;\">#' + (idx + 1) + '</strong></td>' +\n        '<td><strong>' + escapeHtml(p.username) + '</strong> ' + (isTop ? '👑' : '') + '</td>' +\n        '<td class=\"num\"><strong>$' + fmt(p.total_assets) + '</strong></td>' +\n        '<td style=\"text-align:right;\"><span class=\"whale-chip\">' + (idx < 3 ? '🏆 頂級巨鯨' : '操盤手') + '</span></td>';\n      tbody.appendChild(tr);\n    });\n  } catch(e) {}\n}\n\n// 渲染所有 6 檔股票的卡片網格\nfunction escapeHtml(value) {\n  var element=document.createElement('span');element.textContent=String(value ?? '');return element.innerHTML.replaceAll('\"','&quot;').replaceAll(\"'\",'&#39;');\n}\nfunction renderChartsGrid() {\n  var grid = document.getElementById('charts-grid');\n  var wanted = new Set(currentStocks.map(function(stock){return stock.symbol;}));\n  Array.from(grid.children).forEach(function(card){if(!wanted.has(card.dataset.chartSymbol))card.remove();});\n  if(expandedStock && !wanted.has(expandedStock))expandedStock=null;\n\n  currentStocks.forEach(function(stock) {\n    var existing=Array.from(grid.children).find(function(card){return card.dataset.chartSymbol===stock.symbol;});\n    if(existing){\n      var difference=stock.price-(stock.ref_price||stock.price);\n      var rate=stock.ref_price?difference/stock.ref_price*100:0;\n      existing.classList.toggle('active-chart',stock.symbol===selectedSymbol);\n      var badge=existing.querySelector('h3 span:last-child');\n      badge.textContent=(difference>=0?'▲ +':'▼ ')+Math.abs(rate).toFixed(2)+'%';\n      badge.style.color=difference>=0?'var(--green)':'var(--red)';\n      existing.querySelector('.chart-price').textContent='$'+fmt(stock.price);\n      renderMiniPolyline(existing.querySelector('svg'),existing.querySelector('.chart-time-note'),cachedHistories[stock.symbol]||[],stock);\n      var container=existing.querySelector('.stock-fills');\n      var related=recentMarketFills.filter(function(f){return f.symbol===stock.symbol;});\n      var lines=related.map(function(f){return formatFillTime(f.created_at)+' · '+f.buyer_name+(f.buyer_is_bot?'（機器人）':'')+' 買進 '+fmtInt(f.shares)+' 股；'+f.seller_name+(f.seller_is_bot?'（機器人）':'')+' 賣出 '+fmtInt(f.shares)+' 股 · '+fmt(f.price)+' 元';});\n      var signature=JSON.stringify([marketFillsAvailable,lines]);\n      if(container.dataset.signature!==signature){\n        var top=container.scrollTop;\n        container.replaceChildren();\n        if(!lines.length)container.textContent=marketFillsAvailable?'近期沒有成交紀錄':'近期成交資料暫時無法取得';\n        lines.forEach(function(text){var row=document.createElement('div');row.className='fill-row';row.textContent=text;container.appendChild(row);});\n        container.dataset.signature=signature;container.scrollTop=top;\n      }\n      return;\n    }\n    var history = cachedHistories[stock.symbol] || [];\n    var card = document.createElement('div');\n    card.className = 'chart' + (stock.symbol === selectedSymbol ? ' active-chart' : '');\n    card.setAttribute('data-chart-symbol', stock.symbol);\n\n\n    var diff = stock.price - (stock.ref_price || stock.price);\n    var pct = stock.ref_price ? (diff / stock.ref_price * 100) : 0;\n    var isUp = diff >= 0;\n\n    card.innerHTML = '<h3>' +\n        '<span>' + (stock.nickname || stock.name) + '</span>' +\n        '<span style=\"font-size:12px; color:' + (isUp ? 'var(--green)' : 'var(--red)') + '; font-weight:700;\">' +\n          (isUp ? '▲ +' : '▼ ') + Math.abs(pct).toFixed(2) + '%' +\n        '</span>' +\n      '</h3>' +\n      '<div class=\"chart-price\">$' + fmt(stock.price) + '</div>' +\n      '<div class=\"chart-note\"></div>' +\n      '<svg viewBox=\"0 0 400 110\" preserveAspectRatio=\"none\"><polyline fill=\"none\" stroke=\"' + (isUp ? '#78a990' : '#c08383') + '\" stroke-width=\"2\" points=\"10,55 390,55\"></polyline></svg>' +\n      '<div class=\"chart-note chart-time-note\" style=\"font-size:11px;\"></div>' +\n      '<button type=\"button\" class=\"chart-action\" aria-label=\"' + (stock.nickname || stock.name) + ' 行情買進\" onclick=\"openTrade(\\'' + stock.symbol + '\\',\\'BUY\\')\">' +\n        (stock.nickname || stock.name) + ' 買進' +\n      '</button>' +\n      '<button type=\"button\" class=\"chart-action sell\" onclick=\"openTrade(\\'' + stock.symbol + '\\',\\'SELL\\')\">' +\n        (stock.nickname || stock.name) + ' 賣出' +\n      '</button>'; \n\n    var detailButton=document.createElement('button');\n    detailButton.type='button';\n    detailButton.className='stock-detail-toggle';\n    detailButton.textContent=expandedStock===stock.symbol?'收合成交明細':'查看近期成交明細';\n    detailButton.setAttribute('aria-expanded',String(expandedStock===stock.symbol));\n    card.appendChild(detailButton);\n    {\n      var details=document.createElement('div'); details.className='stock-fills';\n      details.hidden=expandedStock!==stock.symbol;\n      detailButton.onclick=function(e){e.stopPropagation();var opening=details.hidden;document.querySelectorAll('.stock-fills').forEach(function(el){el.hidden=true;});document.querySelectorAll('.stock-detail-toggle').forEach(function(el){el.setAttribute('aria-expanded','false');el.textContent='查看近期成交明細';});details.hidden=!opening;expandedStock=opening?stock.symbol:null;detailButton.setAttribute('aria-expanded',String(opening));detailButton.textContent=opening?'收合成交明細':'查看近期成交明細';};\n      var related=recentMarketFills.filter(function(f){return f.symbol===stock.symbol;});\n      if(!related.length)details.textContent=marketFillsAvailable?'近期沒有成交紀錄':'近期成交資料暫時無法取得';\n      related.forEach(function(f){var row=document.createElement('div');row.className='fill-row';row.textContent=formatFillTime(f.created_at)+' · '+f.buyer_name+(f.buyer_is_bot?'（機器人）':'')+' 買進 '+fmtInt(f.shares)+' 股；'+f.seller_name+(f.seller_is_bot?'（機器人）':'')+' 賣出 '+fmtInt(f.shares)+' 股 · '+fmt(f.price)+' 元';details.appendChild(row);});\n      details.dataset.signature=JSON.stringify([marketFillsAvailable,related.map(function(f){return formatFillTime(f.created_at)+' · '+f.buyer_name+(f.buyer_is_bot?'（機器人）':'')+' 買進 '+fmtInt(f.shares)+' 股；'+f.seller_name+(f.seller_is_bot?'（機器人）':'')+' 賣出 '+fmtInt(f.shares)+' 股 · '+fmt(f.price)+' 元';})]);\n      card.appendChild(details);\n    }\n    var svg = card.querySelector('svg');\n    var timeNote = card.querySelector('.chart-time-note');\n    renderMiniPolyline(svg, timeNote, history, stock);\n    grid.appendChild(card);\n  });\n}\n\nfunction renderHeroChart(points) {\n  var stock = currentStocks.find(function(s) { return s.symbol === selectedSymbol; });\n  if (!stock) return;\n  var svg = document.getElementById('hero-svg');\n  var ref = Number(stock.ref_price || stock.price);\n  var curPrice = Number(stock.price);\n\n  var prices = points.map(function(p) { return Number(p.price); });\n  if (!prices.length) {\n    prices = [ref * 0.998, ref, curPrice];\n  } else if (prices.length === 1) {\n    prices = [ref, prices[0]];\n  }\n\n  // 確保 Y 軸刻度有合適的百分比視野 (至少 ±2% 範圍)，避免微小 5 分錢的跳動被過度放大成混亂的抖動\n  var actualMin = Math.min.apply(null, prices.concat([ref]));\n  var actualMax = Math.max.apply(null, prices.concat([ref]));\n  var minSpan = ref * 0.035; // 至少 3.5% 的上下刻度跨度\n  var centerPrice = ref;\n  var halfSpan = Math.max((actualMax - actualMin) / 1.8, minSpan / 2);\n  var yMin = Math.floor((centerPrice - halfSpan) * 10) / 10;\n  var yMax = Math.ceil((centerPrice + halfSpan) * 10) / 10;\n  var ySpan = yMax - yMin;\n\n  var W = 800;\n  var H = 240;\n  var padLeft = 20;\n  var padRight = 75; // 右側留白給 Y 軸價格單位刻度\n  var padTop = 25;\n  var padBottom = 30; // 底部留白給時間刻度\n  var chartW = W - padLeft - padRight;\n  var chartH = H - padTop - padBottom;\n\n  var isUp = curPrice >= ref;\n  var strokeColor = isUp ? '#00f59b' : '#ff3366';\n\n  // Y 軸 4 條水平刻度參考線與標籤\n  var gridLevels = [\n    { price: yMax, label: '$' + fmt(yMax) },\n    { price: ref + (yMax - ref) * 0.5, label: '$' + fmt(ref + (yMax - ref) * 0.5) },\n    { price: ref, label: '平盤 $' + fmt(ref), isRef: true },\n    { price: ref - (ref - yMin) * 0.5, label: '$' + fmt(ref - (ref - yMin) * 0.5) },\n    { price: yMin, label: '$' + fmt(yMin) }\n  ];\n\n  var gridSvg = '';\n  gridLevels.forEach(function(lvl) {\n    var y = padTop + (1 - (lvl.price - yMin) / ySpan) * chartH;\n    var lineStroke = lvl.isRef ? '#475569' : '#1e293b';\n    var dash = lvl.isRef ? '4,4' : '2,4';\n    gridSvg += '<line x1=\"' + padLeft + '\" y1=\"' + y.toFixed(1) + '\" x2=\"' + (padLeft + chartW) + '\" y2=\"' + y.toFixed(1) + '\" stroke=\"' + lineStroke + '\" stroke-dasharray=\"' + dash + '\" stroke-width=\"1\"></line>';\n    gridSvg += '<text x=\"' + (W - 10) + '\" y=\"' + (y + 3.5).toFixed(1) + '\" fill=\"' + (lvl.isRef ? '#cbd5e1' : '#64748b') + '\" font-size=\"10.5\" font-weight=\"' + (lvl.isRef ? '700' : '500') + '\" text-anchor=\"end\">' + lvl.label + '</text>';\n  });\n\n  // X 軸動態時間標記 (Robinhood 24-Hour Market Dynamic Ticks)\n  var timeLabels = computeChartDynamicTicks(points, currentChartSpan);\n  var timeSvg = '';\n  timeLabels.forEach(function(label, i) {\n    var x = padLeft + (i / (timeLabels.length - 1)) * chartW;\n    timeSvg += '<text x=\"' + x.toFixed(1) + '\" y=\"' + (H - 10) + '\" fill=\"#94a3b8\" font-size=\"10.5\" font-weight=\"500\" text-anchor=\"' + (i === 0 ? 'start' : (i === timeLabels.length - 1 ? 'end' : 'middle')) + '\">' + label + '</text>';\n  });\n\n  // 主曲線點座標\n  var coords = prices.map(function(p, idx) {\n    var x = (padLeft + (idx / (prices.length - 1)) * chartW).toFixed(1);\n    var y = (padTop + (1 - (p - yMin) / ySpan) * chartH).toFixed(1);\n    return x + ',' + y;\n  }).join(' ');\n\n  var lastX = (padLeft + chartW).toFixed(1);\n  var lastY = (padTop + (1 - (curPrice - yMin) / ySpan) * chartH).toFixed(1);\n\n  var svgInner = '<defs>' +\n      '<linearGradient id=\"hero-grad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">' +\n        '<stop offset=\"0%\" stop-color=\"' + strokeColor + '\" stop-opacity=\"0.28\"/>' +\n        '<stop offset=\"100%\" stop-color=\"' + strokeColor + '\" stop-opacity=\"0.0\"/>' +\n      '</linearGradient>' +\n    '</defs>' +\n    gridSvg +\n    timeSvg +\n    '<polygon fill=\"url(#hero-grad)\" points=\"' + coords + ' ' + lastX + ',' + (padTop + chartH) + ' ' + padLeft + ',' + (padTop + chartH) + '\" />' +\n    '<filter id=\"hero-glow\"><feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"3\" flood-color=\"' + strokeColor + '\" flood-opacity=\"0.65\"/></filter>' +\n    '<polyline fill=\"none\" stroke=\"' + strokeColor + '\" stroke-width=\"2.5\" stroke-linejoin=\"round\" filter=\"url(#hero-glow)\" points=\"' + coords + '\" />' +\n    '<circle cx=\"' + lastX + '\" cy=\"' + lastY + '\" r=\"4.5\" fill=\"' + strokeColor + '\" />' +\n    '<circle cx=\"' + lastX + '\" cy=\"' + lastY + '\" r=\"9\" fill=\"none\" stroke=\"' + strokeColor + '\" stroke-width=\"1.5\" class=\"pulse-ring\" />' +\n    '<line id=\"scrub-line\" x1=\"0\" y1=\"' + padTop + '\" x2=\"0\" y2=\"' + (padTop + chartH) + '\" stroke=\"#94a3b8\" stroke-dasharray=\"2,2\" stroke-width=\"1\" style=\"display:none;\"></line>';\n\n  svg.innerHTML = svgInner;\n\n  document.getElementById('hero-stat-note').textContent = '當日最高 $' + fmt(actualMax) + ' · 最低 $' + fmt(actualMin) + ' · 昨收平盤 $' + fmt(ref);\n\n  // 滑鼠懸浮查價十字線互動 (Scrubber)\n  var box = document.getElementById('hero-chart-box');\n  var pill = document.getElementById('hero-scrub-pill');\n  box.onmousemove = function(e) {\n    var rect = box.getBoundingClientRect();\n    var mouseX = e.clientX - rect.left;\n    var ratio = Math.max(0, Math.min(1, (mouseX - (padLeft / W * rect.width)) / (chartW / W * rect.width)));\n    var idx = Math.round(ratio * (prices.length - 1));\n    var p = prices[idx];\n    if (p !== undefined) {\n      pill.hidden = false;\n      var scrubLine = document.getElementById('scrub-line');\n      var lineX = padLeft + (idx / (prices.length - 1)) * chartW;\n      if (scrubLine) {\n        scrubLine.setAttribute('x1', lineX);\n        scrubLine.setAttribute('x2', lineX);\n        scrubLine.style.display = 'block';\n      }\n      var chg = p - ref;\n      var pct = (chg / ref * 100);\n      document.getElementById('scrub-price').textContent = '$' + fmt(p);\n      var chgEl = document.getElementById('scrub-change');\n      chgEl.textContent = (chg >= 0 ? '+' : '') + fmt(chg) + ' (' + (chg >= 0 ? '+' : '') + pct.toFixed(2) + '%)';\n      chgEl.style.color = chg >= 0 ? 'var(--green)' : 'var(--red)';\n      document.getElementById('scrub-time').textContent = '資料點 #' + (idx + 1);\n    }\n  };\n  box.onmouseleave = function() {\n    pill.hidden = true;\n    var scrubLine = document.getElementById('scrub-line');\n    if (scrubLine) scrubLine.style.display = 'none';\n  };\n}\n\nfunction formatFillTime(value) {\n  var timestamp=historyTime(value);\n  return Number.isFinite(timestamp) ? new Date(timestamp).toLocaleString('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}) : '時間未知';\n}\nfunction historyTime(value) {\n  var text=String(value||'');\n  return Date.parse(text.includes('T') ? text : text.replace(' ','T')+'Z');\n}\nfunction clearChartInteraction(svg) {\n  clearTimeout(svg._inspectionTimer);\n  svg.onpointerdown=null;svg.onpointermove=null;svg.onpointerup=null;svg.onpointercancel=null;svg.onlostpointercapture=null;\n  svg.dataset.inspecting='false';svg.dataset.dragging='false';svg.replaceChildren();\n}\nfunction renderMiniPolyline(svg, note, points, stock) {\n  if(svg.dataset.inspecting==='true') return;\n  svg.setAttribute('role','img');\n  svg.setAttribute('aria-label','歷史價格走勢，虛線為平盤價');\n  var valid=points.map(function(p){return {price:Number(p.price),time:historyTime(p.created_at)};})\n    .filter(function(p){return Number.isFinite(p.price)&&p.price>0&&Number.isFinite(p.time);})\n    .sort(function(a,b){return a.time-b.time;});\n  clearChartInteraction(svg);\n  if(!valid.length){note.textContent='尚無歷史資料';return;}\n  var prices=valid.map(function(p){return p.price;}), ref=Number(stock.ref_price || stock.price);\n  var min=Math.min.apply(null,prices.concat([ref])), max=Math.max.apply(null,prices.concat([ref]));\n  var margin=Math.max((max-min)*.08,ref*.002,0.01); min-=margin;max+=margin;\n  var first=valid[0].time,last=valid[valid.length-1].time,span=last-first;\n  var coords=valid.map(function(p){return (span ? 10+(p.time-first)/span*380 : 200).toFixed(1)+','+(12+(max-p.price)/(max-min)*86).toFixed(1);}).join(' ');\n  var lastPrice=prices[prices.length-1],lastY=12+(max-lastPrice)/(max-min)*86;\n  var color=lastPrice>=ref?'#00f59b':'#ff3366';\n  var baseline=document.createElementNS('http://www.w3.org/2000/svg','line');\n  var refY=12+(max-ref)/(max-min)*86;\n  baseline.setAttribute('x1','10');baseline.setAttribute('x2','390');baseline.setAttribute('y1',refY);baseline.setAttribute('y2',refY);baseline.setAttribute('stroke','#71887a');baseline.setAttribute('stroke-opacity','.55');baseline.setAttribute('stroke-dasharray','4 5');svg.appendChild(baseline);\n  var line=document.createElementNS('http://www.w3.org/2000/svg','polyline');\n  line.setAttribute('fill','none');line.setAttribute('stroke',color);line.setAttribute('stroke-width','2');line.setAttribute('points',coords);line.setAttribute('filter','drop-shadow(0 0 3px '+color+')');svg.appendChild(line);\n  var dot=document.createElementNS('http://www.w3.org/2000/svg','circle');\n  dot.setAttribute('cx',span?'390':'200');dot.setAttribute('cy',lastY);dot.setAttribute('r','3');dot.setAttribute('fill',color);svg.appendChild(dot);\n  var time=function(t){return new Date(t).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});};\n  note.textContent=(valid.length===1?'一筆紀錄 ':time(first)+'–'+time(last)+' · ')+'最高 '+fmt(Math.max.apply(null,prices))+' · 最低 '+fmt(Math.min.apply(null,prices))+' · 虛線：平盤 '+fmt(ref);\n  var summary=note.textContent;\n  svg.setAttribute('aria-label','歷史價格走勢，虛線為平盤價；按住圖表查看資料');\n  function inspect(event){\n    var rect=svg.getBoundingClientRect();\n    var fraction=Math.max(0,Math.min(1,((event.clientX-rect.left)/rect.width*400-10)/380));\n    var target=first+fraction*span;\n    var point=valid.reduce(function(best,p){return Math.abs(p.time-target)<=Math.abs(best.time-target)?p:best;},valid[0]);\n    var x=span?10+(point.time-first)/span*380:200;\n    var marker=svg.querySelector('.chart-inspect-line');\n    if(!marker){marker=document.createElementNS('http://www.w3.org/2000/svg','line');marker.classList.add('chart-inspect-line');marker.setAttribute('y1','10');marker.setAttribute('y2','100');marker.setAttribute('stroke','#d5e5d9');marker.setAttribute('stroke-dasharray','3 4');svg.appendChild(marker);}\n    marker.setAttribute('x1',x);marker.setAttribute('x2',x);\n    note.textContent=time(point.time)+' · '+fmt(point.price)+(svg.id==='index-chart'?' 點 · 基準 ':' 元 · 平盤 ')+fmt(ref);\n  }\n  svg.onpointerdown=function(event){svg.dataset.inspecting='true';svg.dataset.dragging='true';svg.setPointerCapture(event.pointerId);inspect(event);};\n  svg.onpointermove=function(event){if(svg.dataset.dragging==='true')inspect(event);};\n  function clearInspection(){svg.dataset.inspecting='false';svg.dataset.dragging='false';var marker=svg.querySelector('.chart-inspect-line');if(marker)marker.remove();note.textContent=summary;}\n  function finish(){svg.dataset.dragging='false';clearTimeout(svg._inspectionTimer);svg._inspectionTimer=setTimeout(clearInspection,4000);}\n  var startInspect=svg.onpointerdown;\n  svg.onpointerdown=function(event){clearTimeout(svg._inspectionTimer);startInspect(event);};\n  svg.onpointerup=finish;svg.onpointercancel=clearInspection;svg.onlostpointercapture=finish;\n}\nfunction renderIndexHistory(stocks) {\n  var all=stocks.map(function(s){return (cachedHistories[s.symbol]||[]).map(function(p){return {price:Number(p.price),time:historyTime(p.created_at)};}).filter(function(p){return Number.isFinite(p.time)&&p.price>0;}).sort(function(a,b){return a.time-b.time;});});\n  var svg=document.getElementById('index-chart'),note=document.getElementById('index-chart-note');\n  if(all.some(function(series){return !series.length;})){clearChartInteraction(svg);note.textContent='歷史資料不足，暫時無法繪製指數';return;}\n  var times=Array.from(new Set(all.flatMap(function(series){return series.map(function(p){return p.time;});}))).sort(function(a,b){return a-b;});\n  var positions=all.map(function(){return 0;}),points=[];\n  times.forEach(function(t){var sum=0,ready=true;all.forEach(function(series,i){while(positions[i]+1<series.length&&series[positions[i]+1].time<=t)positions[i]++;if(series[positions[i]].time>t){ready=false;return;}sum+=indexWeights[stocks[i].symbol]*(series[positions[i]].price/stocks[i].ref_price);});if(ready)points.push({price:1000*sum,created_at:new Date(t).toISOString()});});\n  renderMiniPolyline(svg,note,points,{ref_price:1000,price:points.length?points[points.length-1].price:1000});\n}\n\nfunction renderBook(bids, asks) {\n  var tbody = document.getElementById('book');\n  tbody.innerHTML = '';\n  var allQtys = bids.map(function(b) { return b.shares; }).concat(asks.map(function(a) { return a.shares; }));\n  var maxQty = allQtys.length ? Math.max.apply(null, allQtys) : 100;\n  if (maxQty < 100) maxQty = 100;\n\n  for (var i = 0; i < 5; i++) {\n    var b = bids[i];\n    var a = asks[i];\n    var tr = document.createElement('tr');\n    var bPct = b ? (b.shares / maxQty * 100).toFixed(0) : 0;\n    var aPct = a ? (a.shares / maxQty * 100).toFixed(0) : 0;\n\n    tr.innerHTML = '<td>' + (b ? b.orders + ' 筆' : '-') + '</td>' +\n      '<td class=\"num book-bar\">' +\n        '<div class=\"book-bar-fill bid\" style=\"width:' + bPct + '%;\"></div>' +\n        '<span class=\"book-content\">' + (b ? fmtInt(b.shares) : '-') + '</span>' +\n      '</td>' +\n      '<td class=\"num\" style=\"color:var(--green); font-weight:700;\">' + (b ? '$' + fmt(b.price) : '-') + '</td>' +\n      '<td class=\"num\" style=\"color:var(--red); font-weight:700;\">' + (a ? '$' + fmt(a.price) : '-') + '</td>' +\n      '<td class=\"num book-bar\">' +\n        '<div class=\"book-bar-fill ask\" style=\"width:' + aPct + '%;\"></div>' +\n        '<span class=\"book-content\">' + (a ? fmtInt(a.shares) : '-') + '</span>' +\n      '</td>' +\n      '<td class=\"num\">' + (a ? a.orders + ' 筆' : '-') + '</td>';\n    tbody.appendChild(tr);\n  }\n}\n\nasync function showBook(symbol) {\n  try {\n    var res = await fetch('/api/orderbook?symbol=' + encodeURIComponent(symbol));\n    if (!res.ok) return;\n    var data = await res.json();\n    renderBook(data.bids || [], data.asks || []);\n  } catch(e) {}\n}\n\nvar tradeOpener=null, tradeOpenerAction=null;\ndocument.getElementById('trade-dialog').addEventListener('close',function(){\n  var target=tradeOpener && tradeOpener.isConnected ? tradeOpener : Array.from(document.querySelectorAll('button[onclick]')).find(function(button){return button.getAttribute('onclick')===tradeOpenerAction && button.getClientRects().length;});\n  if(target)target.focus({preventScroll:true});\n});\n\nvar currentChartSpan = '1D';\nvar tradeUnitMode = 'SHARES';\n\nfunction setChartSpan(span) {\n  currentChartSpan = span;\n  document.querySelectorAll('.time-tab').forEach(function(tab) {\n    tab.classList.toggle('active', tab.dataset.span === span);\n  });\n  if (cachedHistories[selectedSymbol]) {\n    renderHeroChart(cachedHistories[selectedSymbol]);\n  }\n}\n\nfunction computeChartDynamicTicks(points, span) {\n  if (span === '1W') return ['週一', '週二', '週三', '週四', '今日實時'];\n  if (span === '1M') return ['4週前', '3週前', '2週前', '上週', '今日實時'];\n  \n  // 1D or 24H: 根據即時目前時間動態產生 24 小時/當前連續刻度\n  var now = new Date();\n  var ticks = [];\n  var intervals = [60, 45, 30, 15, 0];\n  for (var i = 0; i < intervals.length; i++) {\n    var mins = intervals[i];\n    if (mins === 0) {\n      ticks.push('即時實況');\n    } else {\n      var d = new Date(now.getTime() - mins * 60000);\n      var hh = String(d.getHours()).padStart(2, '0');\n      var mm = String(d.getMinutes()).padStart(2, '0');\n      ticks.push(hh + ':' + mm);\n    }\n  }\n  return ticks;\n}\n\nfunction setTradeUnitMode(mode) {\n  tradeUnitMode = mode;\n  var isDollars = (mode === 'DOLLARS');\n  var btnShares = document.getElementById('trade-mode-shares');\n  var btnDollars = document.getElementById('trade-mode-dollars');\n  var dollarField = document.getElementById('dollar-input-field');\n  if (btnShares) btnShares.classList.toggle('active', !isDollars);\n  if (btnDollars) btnDollars.classList.toggle('active', isDollars);\n  if (dollarField) dollarField.hidden = !isDollars;\n  var sharesInput = document.getElementById('trade-shares');\n  if (sharesInput) sharesInput.readOnly = false;\n  if (isDollars) {\n    onDollarInput();\n  } else {\n    updateTradeSummary();\n  }\n}\n\nfunction onDollarInput() {\n  var stock = currentStocks.find(function(s) { return s.symbol === selectedSymbol; });\n  if (!stock) return;\n  var dollars = parseFloat(document.getElementById('trade-dollars').value) || 0;\n  var type = document.getElementById('trade-type').value;\n  var limitPrice = parseFloat(document.getElementById('trade-price').value) || stock.price;\n  var execPrice = type === 'LIMIT' ? limitPrice : stock.price;\n  if (dollars > 0 && execPrice > 0) {\n    var feePerShare = execPrice * 0.001425;\n    var shares = Math.max(1, Math.floor(dollars / (execPrice + feePerShare)));\n    document.getElementById('trade-shares').value = shares;\n  }\n  updateTradeSummary();\n}\n\n// Robinhood 滑動下單 (Swipe to Confirm) 互動引擎\nfunction setupSwipeTrack() {\n  var track = document.getElementById('swipe-track');\n  var thumb = document.getElementById('swipe-thumb');\n  var fill = document.getElementById('swipe-fill');\n  var text = document.getElementById('swipe-text');\n  if (!track || !thumb || !fill || !text) return;\n  var isDragging = false;\n  var startX = 0;\n  var maxSlide = 0;\n\n  function onPointerDown(e) {\n    if (isSubmitting) return;\n    isDragging = true;\n    startX = e.clientX || (e.touches && e.touches[0].clientX) || 0;\n    maxSlide = track.clientWidth - thumb.clientWidth - 8;\n    if (thumb.setPointerCapture) {\n      try { thumb.setPointerCapture(e.pointerId); } catch(err) {}\n    }\n  }\n\n  function onPointerMove(e) {\n    if (!isDragging || isSubmitting) return;\n    var clientX = e.clientX || (e.touches && e.touches[0].clientX) || 0;\n    var deltaX = Math.max(0, Math.min(maxSlide, clientX - startX));\n    thumb.style.transform = 'translateX(' + deltaX + 'px)';\n    fill.style.width = (deltaX + 20) + 'px';\n    var progress = maxSlide > 0 ? (deltaX / maxSlide) : 0;\n    text.style.opacity = Math.max(0, 1 - progress * 1.5);\n\n    if (progress >= 0.88) {\n      isDragging = false;\n      thumb.style.transform = 'translateX(' + maxSlide + 'px)';\n      fill.style.width = '100%';\n      text.textContent = '訂單處理中...';\n      document.getElementById('confirm-trade').click();\n      setTimeout(resetSwipe, 900);\n    }\n  }\n\n  function onPointerUp() {\n    if (!isDragging) return;\n    isDragging = false;\n    resetSwipe();\n  }\n\n  function resetSwipe() {\n    thumb.style.transition = 'transform 0.25s var(--apple-ease)';\n    fill.style.transition = 'width 0.25s var(--apple-ease)';\n    thumb.style.transform = 'translateX(0px)';\n    fill.style.width = '0%';\n    setTimeout(function() {\n      thumb.style.transition = '';\n      fill.style.transition = '';\n      text.style.opacity = '1';\n      text.textContent = activeTradeSide === 'BUY' ? '滑動確認買進 ➜' : '滑動確認賣出 ➜';\n    }, 250);\n  }\n\n  thumb.onpointerdown = onPointerDown;\n  window.addEventListener('pointermove', onPointerMove);\n  window.addEventListener('pointerup', onPointerUp);\n}\n\nfunction openTrade(symbol, side) {\n  if(isSubmitting)return;\n  tradeOpener=document.activeElement;\n  tradeOpenerAction=tradeOpener && tradeOpener.getAttribute('onclick');\n  var stock = currentStocks.find(function(s) { return s.symbol === symbol; });\n  if (!stock) return;\n  selectedSymbol = symbol;\n  activeTradeSide = side;\n\n  var dialog = document.getElementById('trade-dialog');\n  document.getElementById('trade-title').textContent = (stock.nickname || stock.name) + ' · ' + (side === 'BUY' ? '買進下單' : '賣出下單');\n  document.getElementById('trade-type').value = 'MARKET';\n  document.getElementById('trade-shares').value = '10';\n  document.getElementById('trade-price').value = stock.price;\n  document.getElementById('price-field').hidden = true;\n  document.getElementById('trade-error').textContent = '';\n\n  var confirmBtn = document.getElementById('confirm-trade');\n  confirmBtn.textContent = side === 'BUY' ? '確認買進' : '確認賣出';\n  confirmBtn.className = side === 'BUY' ? 'buy' : 'sell';\n  var swipeTrack = document.getElementById('swipe-track');\n  if (swipeTrack) swipeTrack.className = 'swipe-track ' + (side === 'BUY' ? '' : 'sell-mode');\n  var swipeText = document.getElementById('swipe-text');\n  if (swipeText) swipeText.textContent = side === 'BUY' ? '滑動確認買進 ➜' : '滑動確認賣出 ➜';\n  setTradeUnitMode('SHARES');\n  var bpEl = document.getElementById('dialog-buying-power');\n  if (bpEl && currentAccount) {\n    var avail = Math.max(0, Number(currentAccount.account.cash) - Number(currentAccount.account.frozen_cash || 0));\n    bpEl.textContent = '$' + fmt(avail * (isTurbo ? 5 : 1));\n  }\n  setupSwipeTrack();\n\n  updateTradeSummary();\n  dialog.showModal();\n}\n\nfunction addShares(n) {\n  var el = document.getElementById('trade-shares');\n  el.value = Math.max(1, (parseInt(el.value) || 0) + n);\n  updateTradeSummary();\n}\n\nfunction setQuickShares(ratio) {\n  var stock=currentStocks.find(function(s){return s.symbol===selectedSymbol;});\n  if(!stock||!currentAccount)return;\n  var quantity=0;\n  if(activeTradeSide==='BUY'){\n    var availableCents=Math.max(0,Math.round(Number(currentAccount.account.cash)*100)-Math.round(Number(currentAccount.account.frozen_cash||0)*100));\n    var isLimit=document.getElementById('trade-type').value==='LIMIT';\n    var price=isLimit?Number(document.getElementById('trade-price').value):Number(stock.price);\n    if(!Number.isFinite(price)||price<=0){document.getElementById('trade-error').textContent='請先輸入有效價格';return;}\n    var cents=Math.round(price*100);\n    if(cents<=0){document.getElementById('trade-error').textContent='請先輸入有效價格';return;}\n    var feePerShare=Math.ceil(cents*1425/1000000);\n    quantity=Math.floor((availableCents * (isTurbo ? 5 : 1))/(cents+feePerShare)*ratio);\n  }else{\n    var holding=(currentAccount.holdings||[]).find(function(h){return h.symbol===selectedSymbol;});\n    quantity=Math.floor(Math.max(0,(holding?holding.shares:0)-(holding?holding.frozen_shares:0))*ratio);\n  }\n  document.getElementById('trade-shares').value=quantity>0?quantity:'';\n  document.getElementById('trade-error').textContent=quantity>0?'':(activeTradeSide==='BUY'?'可用資金不足':'沒有可賣出的股票');\n  updateTradeSummary();\n}\n\ndocument.getElementById('trade-type').onchange = function(e) {\n  document.getElementById('trade-error').textContent='';\n  document.getElementById('price-field').hidden = (e.target.value !== 'LIMIT');\n  var exp = document.getElementById('trade-type-explainer');\n  if (exp) exp.textContent = (e.target.value === 'LIMIT') ? '限價單：設定最高買入或最低賣出價，杜絕意外滑價。' : '市價單：以當前市場最優價格即時撮合，成交速度最快。';\n  updateTradeSummary();\n};\nfunction onTradeInput(){document.getElementById('trade-error').textContent='';updateTradeSummary();}\ndocument.getElementById('trade-shares').oninput = onTradeInput;\ndocument.getElementById('trade-price').oninput = onTradeInput;\nvar dollarEl = document.getElementById('trade-dollars');\nif (dollarEl) dollarEl.oninput = onDollarInput;\n\nfunction updateTradeSummary() {\n  var stock = currentStocks.find(function(s) { return s.symbol === selectedSymbol; });\n  if (!stock) return;\n  var type = document.getElementById('trade-type').value;\n  var shares = Number(document.getElementById('trade-shares').value) || 0;\n  document.getElementById('confirm-trade').disabled=isSubmitting || !Number.isSafeInteger(shares) || shares<1;\n  var limitPrice = parseFloat(document.getElementById('trade-price').value) || stock.price;\n  var execPrice = type === 'LIMIT' ? limitPrice : stock.price;\n  var estAmount = execPrice * shares;\n  var fee = Math.ceil(Math.round(execPrice * 100) * shares * 1425 / 1000000) / 100;\n  var total = estAmount + (activeTradeSide === 'BUY' ? fee : -fee);\n  var isWhale = shares >= 50 || isTurbo;\n\n  var range=document.getElementById('trade-price-range');\n  var refCents=Math.round(Number(stock.ref_price)*100);\n  if(Number.isFinite(refCents) && refCents>0) {\n    var low=Math.ceil(refCents*.9)/100, high=Math.floor(refCents*1.1)/100;\n    range.textContent='今日限價範圍：'+fmt(low)+'～'+fmt(high)+' 元';\n  } else range.textContent='平盤價格暫時無法取得';\n  var box = document.getElementById('trade-summary');\n  box.innerHTML = '';\n  function row(label, val) {\n    var div = document.createElement('div');\n    div.className = 'summary-row';\n    div.innerHTML = '<span>' + label + '</span><strong>' + val + '</strong>';\n    box.appendChild(div);\n  }\n  row('標的股票', stock.nickname || stock.name);\n  row('委託類型', type === 'MARKET' ? '市價委託' : '限價委託');\n  if (isTurbo) row('交易模式', '🔥 狂暴 5X 槓桿 (保證金購買力放大 500%)');\n  row('預估每股價格', '$' + fmt(execPrice));\n  row('預估手續費', '$' + fmt(fee));\n  row(activeTradeSide === 'BUY' ? '預估費用與成本' : '預估實收現金', '$' + fmt(Math.max(0, total)));\n\n  if (isWhale) {\n    var alertRow = document.createElement('div');\n    alertRow.style.color = '#fbbf24';\n    alertRow.style.fontSize = '12px';\n    alertRow.style.marginTop = '6px';\n    alertRow.textContent = '👑 巨鯨掃單：大單將吃穿多檔深度，直接影響市場價格！';\n    box.appendChild(alertRow);\n  }\n  if (type === 'MARKET') {\n    var tip = document.createElement('div');\n    tip.style.color = 'var(--text-muted)';\n    tip.style.fontSize = '11.5px';\n    tip.style.marginTop = '4px';\n    tip.textContent = '※ 市價可能不同且不保證以現價完全成交，將由訂單簿依序撮合。';\n    box.appendChild(tip);\n  }\n}\n\ndocument.getElementById('confirm-trade').onclick = async function() {\n  if (isSubmitting) return;\n  var stock = currentStocks.find(function(s) { return s.symbol === selectedSymbol; });\n  if (!stock) return;\n  var type = document.getElementById('trade-type').value;\n  var shares = Number(document.getElementById('trade-shares').value);\n  var limitPrice = parseFloat(document.getElementById('trade-price').value);\n  var errEl = document.getElementById('trade-error');\n  errEl.textContent = '';\n\n  if (!Number.isSafeInteger(shares) || shares < 1) { errEl.textContent = '請輸入正整數股數'; return; }\n  if (type === 'LIMIT' && (!Number.isFinite(limitPrice) || limitPrice <= 0)) { errEl.textContent = '請輸入有效限價'; return; }\n  if (type === 'LIMIT' && Number(stock.ref_price)>0) {\n    var refCents=Math.round(Number(stock.ref_price)*100), priceCents=Math.round(limitPrice*100);\n    if(priceCents<Math.ceil(refCents*.9) || priceCents>Math.floor(refCents*1.1)) {\n      errEl.textContent='限價超出今日範圍，請參考上方提示';return;\n    }\n  }\n\n  isSubmitting = true;\n  document.getElementById('confirm-trade').disabled = true;\n  document.getElementById('cancel-trade').disabled = true;\n  var orderController=new AbortController();\n  var orderTimer=setTimeout(function(){orderController.abort();},20000);\n\n  try {\n    var body = {\n      symbol: stock.symbol,\n      side: activeTradeSide,\n      type: type,\n      shares: shares,\n      price: type === 'LIMIT' ? limitPrice : null,\n      request_id: 'order-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8)\n    };\n    var res = await fetch('/api/orders', {\n      method: 'POST',\n      signal: orderController.signal,\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(body)\n    });\n    var data = await res.json();\n    if (data.ok) {\n      document.getElementById('trade-dialog').close();\n      if (data.status === 'FILLED' || (data.filledShares && data.filledShares > 0)) {\n        toast('🎉 成功成交 ' + fmtInt(data.filledShares) + ' 股！均價 $' + fmt(data.avgPrice || stock.price), true);\n        if (activeTradeSide === 'BUY') playBuyChime(); else playSellChime();\n        if (data.filledShares >= 50 || isTurbo) {\n          playWhaleBoom();\n          triggerWhaleShake();\n        }\n      } else if (data.status === 'CANCELLED') {\n        toast('委託已取消', false);\n      } else {\n        toast('委託已送出，掛單等待撮合中', true);\n        playTone(440, 'sine', 0.1);\n      }\n      await pollLive();\n    } else {\n      errEl.textContent = data.message || '委託失敗';\n      toast(data.message || '委託失敗', false);\n    }\n  } catch(e) {\n    errEl.textContent = '連線中斷，委託結果尚未確認，請先查看委託與成交紀錄';\n  } finally {\n    clearTimeout(orderTimer);\n    isSubmitting = false;\n    document.getElementById('cancel-trade').disabled = false;\n    updateTradeSummary();\n  }\n};\n\ndocument.getElementById('trade-dialog').addEventListener('cancel',function(event){if(isSubmitting)event.preventDefault();});\ndocument.getElementById('cancel-trade').onclick = function() { if(!isSubmitting)document.getElementById('trade-dialog').close(); };\n\nfunction openCancel(orderId) {\n  cancelOrderId = orderId;\n  document.getElementById('cancel-dialog').showModal();\n}\ndocument.getElementById('confirm-cancel').onclick = async function() {\n  if (!cancelOrderId) return;\n  try {\n    var res = await fetch('/api/orders/' + cancelOrderId, { method: 'DELETE' });\n    var data = await res.json();\n    document.getElementById('cancel-dialog').close();\n    if (data.ok) {\n      toast('委託已取消', true);\n      await pollLive();\n    } else {\n      toast(data.message || '取消失敗', false);\n    }\n  } catch(e) {\n    toast('連線失敗', false);\n  }\n};\n\nrefreshSession();\n\n// 智慧單一請求輪詢：僅在分頁處於可見狀態時，每 3 秒發送一次 /api/live 請求\nvar autoPollInFlight = false;\nsetInterval(function() {\n  if (signedIn && !document.hidden && !isSubmitting && !autoPollInFlight) {\n    autoPollInFlight = true;\n    pollLive().finally(function(){autoPollInFlight=false;});\n  }\n}, 10000);\n\n</script>\n</body>\n</html>";
